insert into public.module ("slug", "order", "description", "status", "title", "purpose", "kind", "subtitle", "id", "created_date", "updated_date") values ('check-the-story-build-evidence', 4, 'Keep an event, criticism or setback from automatically becoming a permanent verdict about the person. Accuracy, not forced positivity.', 'live', 'Check the Story, Build Evidence', 'Keep an event, criticism or setback from automatically becoming a permanent verdict about the person. Accuracy, not forced positivity.', 'module', null, '6acfc07f4c60e3002b7557a1', '2026-10-14T17:48:47.070000'::timestamptz, '2026-10-14T17:48:47.070000'::timestamptz) on conflict (id) do update set "slug" = excluded."slug", "order" = excluded."order", "description" = excluded."description", "status" = excluded."status", "title" = excluded."title", "purpose" = excluded."purpose", "kind" = excluded."kind", "subtitle" = excluded."subtitle", "created_date" = excluded."created_date", "updated_date" = excluded."updated_date";
insert into public.module ("slug", "order", "description", "status", "title", "purpose", "kind", "subtitle", "id", "created_date", "updated_date") values ('test-how-i-operate', 3, 'Test whether one setup change makes an activity more chosen, flexible or workable—not identify a learner type.', 'live', 'Test How I Operate', 'Test whether one setup change makes an activity more chosen, flexible or workable—not identify a learner type.', 'module', null, '6acfc07f4c60e3002b7557a0', '2026-10-14T17:48:47.070000'::timestamptz, '2026-10-14T17:48:47.070000'::timestamptz) on conflict (id) do update set "slug" = excluded."slug", "order" = excluded."order", "description" = excluded."description", "status" = excluded."status", "title" = excluded."title", "purpose" = excluded."purpose", "kind" = excluded."kind", "subtitle" = excluded."subtitle", "created_date" = excluded."created_date", "updated_date" = excluded."updated_date";
insert into public.module ("description", "kind", "order", "purpose", "slug", "status", "subtitle", "title", "id", "created_date", "updated_date") values ('Listen to how an activity is going, then protect what already works or make one small reversible adjustment. The instrument is how you are engaging right now, not you. Useful does not have to mean calm.', 'module', 5, 'Listen to how an activity is going, then protect what already works or make one small reversible adjustment. The instrument is how you are engaging right now, not you. Useful does not have to mean calm.', 'protect-what-works', 'live', null, 'Tuning Your Instrument', '6acfc07f4c60e3002b7557a2', '2026-10-14T17:48:47.070000'::timestamptz, '2026-10-20T03:20:44.826000'::timestamptz) on conflict (id) do update set "description" = excluded."description", "kind" = excluded."kind", "order" = excluded."order", "purpose" = excluded."purpose", "slug" = excluded."slug", "status" = excluded."status", "subtitle" = excluded."subtitle", "title" = excluded."title", "created_date" = excluded."created_date", "updated_date" = excluded."updated_date";
insert into public.lesson ("alias", "approval_note", "approval_state", "approved_source", "approved_version", "boundary", "carry_forward", "code", "decision_options", "description", "duration_min", "has_decision", "module_order", "order", "purpose", "readings_note", "reflect_prompts", "routes", "show", "status", "teach", "title", "try_prompts", "type", "what_comes_out", "id", "created_date", "updated_date") values (null, null, 'pending_approval', 'Ashley approved the Life Map–Module 1 revision proposal in conversation, October 18, 2026. New wording prepared for review.', 'Working revision, October 18, 2026', null, '["M1-L1","O.4"]'::jsonb, 'M1-L3', '[]'::jsonb, 'Close Module 1 with a short individual learning agreement before exploring experiences in Module 2.', 8, false, 1, 3, 'Set a revisable agreement about your own learning and the support that will make exploration workable.', null, '["When would it be useful to revisit this agreement—for example, after your first experience or if your circumstances change?","Optional: What’s one thing you believe about yourself that you haven’t had the opportunity to test? You’ll see it again in Module 4."]'::jsonb, '["Say it","Write it","Watch","Pass"]'::jsonb, null, 'draft', '## Your part

Decide what you are willing to try in Module 2, and give the discussion and reflection questions honest, thoughtful attention. Explain what you notice as fully as you can. This is about taking your own learning seriously. There is no required answer length, and you do not already need to know what interests you.

You can write privately, talk it through with someone you choose, or combine both. “I don’t know yet” and “nothing draws me in” are starting points you can explain and investigate.

## The program’s part

The program offers possibilities to explore, questions to help you reflect, and room to ask for help or adjust your approach. If you filled in “What makes it work for you” in Getting Started, look back at it to identify support you need. Check what support is actually available before making a plan that depends on it.

## Make the agreement yours

Record what you are willing to try and what you need to make that possible. Your exploration question may remain undecided. You can revise this agreement as you learn, change an experience, or pause. Trying something does not commit you to pursuing it afterward.

Module 2 is where you choose and encounter an experience. You do not have to complete one here.', 'Your learning agreement', '["What are you willing to try in Module 2, and how will you give the reflection questions honest attention? Describe it in your own words. Leaving the question open counts.","What observation or question, if any, would you like to bring into Module 2? “Nothing draws me in yet” is a valid starting point.","What support or adjustment would help you take part? You can look back at “What makes it work for you” in Getting Started, or say none for now."]'::jsonb, 'activity', 'A revisable learning agreement: what you are willing to try, a starting question or uncertainty, support needs, and a point to review it.', '6ad56eab7f55c0d23ec398b2', '2026-10-19T01:13:15.662000'::timestamptz, '2026-10-24T02:15:32.491000'::timestamptz) on conflict (id) do update set "alias" = excluded."alias", "approval_note" = excluded."approval_note", "approval_state" = excluded."approval_state", "approved_source" = excluded."approved_source", "approved_version" = excluded."approved_version", "boundary" = excluded."boundary", "carry_forward" = excluded."carry_forward", "code" = excluded."code", "decision_options" = excluded."decision_options", "description" = excluded."description", "duration_min" = excluded."duration_min", "has_decision" = excluded."has_decision", "module_order" = excluded."module_order", "order" = excluded."order", "purpose" = excluded."purpose", "readings_note" = excluded."readings_note", "reflect_prompts" = excluded."reflect_prompts", "routes" = excluded."routes", "show" = excluded."show", "status" = excluded."status", "teach" = excluded."teach", "title" = excluded."title", "try_prompts" = excluded."try_prompts", "type" = excluded."type", "what_comes_out" = excluded."what_comes_out", "created_date" = excluded."created_date", "updated_date" = excluded."updated_date";
insert into public.lesson ("alias", "approval_note", "approval_state", "approved_source", "approved_version", "boundary", "carry_forward", "code", "decision_options", "description", "duration_min", "has_decision", "module_order", "order", "purpose", "readings_note", "reflect_prompts", "routes", "show", "status", "teach", "title", "try_prompts", "type", "what_comes_out", "id", "created_date", "updated_date") values ('7', null, 'pending_approval', 'Entrepalooza Pilot 1 — Module Breakdown (Oct 5, 2026) · adopted Pilot 1 scope', 'Pilot 1 adopted card · lessons database copy Oct 6, 2026', 'Source draft: `06-module-1-facilitator-guide.md`. This is working curriculum content and remains in **Draft** until rehearsed. Keep participant choice, the right to pass, and facilitator boundaries intact.
Source pages (Ashley Zeck workspace): [‣](https://app.notion.com/p/b7a4e722bdf582f2b31781b8928c479e?pvs=21) · [‣](https://app.notion.com/p/a484e722bdf58371b7a381c08ebacb96?pvs=21)', '["M2-L1","M2-L2"]'::jsonb, 'M2-L3', '[]'::jsonb, 'Look back at one experience and decide whether to try again, adjust something, explore a different option, or leave the question open.', 10, true, 2, 3, 'Decide whether a possibility deserves more exploration, based on what actually happened.', null, '["","","","","What did this encounter leave you with: a possibility to explore further, a clearer question, a practical barrier, uncertainty, or a reason to look elsewhere? Describe what supports your answer.","Would another encounter help you learn more? You could change the task or setting, ask a question, repeat something, or choose a different possibility. What would you hope to find out?"]'::jsonb, '["Review an experience","I haven''t tried it yet","Record a decision only","Pass"]'::jsonb, '', 'draft', '## An experience can change your mind

You might be more interested than you expected, less interested, or unsure. Perhaps you enjoyed one part but not another. Maybe the activity appealed to you but the conditions didn''t work. Any of those results can help you choose what to explore next.

You don''t need to reach a conclusion about your personality or your future. Compare what you expected with what you experienced, and consider what still isn''t known.

If you''re ready to choose a direction, the Next Decision options are below. You can continue, change the approach, test again, pause, stop, or look elsewhere. You can also wait until you''ve actually had a chance to try something.

## Look at how interest changes

Interest can grow when you stay with something, learn more about it, and come to value it. It can also fade or stay undeveloped. Initial excitement does not establish a lasting interest. One disappointing encounter does not settle the question either.

As a next step in this program, you can choose another encounter with the same possibility, a different task or setting, more information, or something else. Repeating is an option, not a requirement. If you return to something, compare what changed and what stayed the same.

A useful outcome can be a possibility worth exploring further, a clearer question, a practical barrier, uncertainty, or deciding to look elsewhere. You choose what to bring into Module 3, where you can examine the conditions around a task.', 'What Did You Discover?', '["What was different from what you expected?","","","What do you still want to know?","What might you explore next?"]'::jsonb, 'next_decision', 'Keep whatever you learned, including a new question. A decision is available, not a verdict.', '6ad190ad65d36f46e5536060', '2026-10-16T02:49:17.310000'::timestamptz, '2026-10-24T07:55:29.611000'::timestamptz) on conflict (id) do update set "alias" = excluded."alias", "approval_note" = excluded."approval_note", "approval_state" = excluded."approval_state", "approved_source" = excluded."approved_source", "approved_version" = excluded."approved_version", "boundary" = excluded."boundary", "carry_forward" = excluded."carry_forward", "code" = excluded."code", "decision_options" = excluded."decision_options", "description" = excluded."description", "duration_min" = excluded."duration_min", "has_decision" = excluded."has_decision", "module_order" = excluded."module_order", "order" = excluded."order", "purpose" = excluded."purpose", "readings_note" = excluded."readings_note", "reflect_prompts" = excluded."reflect_prompts", "routes" = excluded."routes", "show" = excluded."show", "status" = excluded."status", "teach" = excluded."teach", "title" = excluded."title", "try_prompts" = excluded."try_prompts", "type" = excluded."type", "what_comes_out" = excluded."what_comes_out", "created_date" = excluded."created_date", "updated_date" = excluded."updated_date";
insert into public.admin_fields (entity, record_id, field, value) values ('Lesson', '6ad190ad65d36f46e5536060', 'internal_notes', '19 Oct 2026. Pilot 1 can support a triggered encounter and a better question. It does not establish a well-developed individual interest. Hidi and Renninger (2006) describe later phases as requiring repeated engagement, knowledge, and stored value. Repeating a try is optional here. Do not tell a participant they have completed a phase of interest development.') on conflict (entity, record_id, field) do update set value = excluded.value;
insert into public.lesson ("alias", "approval_note", "approval_state", "approved_source", "approved_version", "boundary", "carry_forward", "code", "decision_options", "description", "duration_min", "has_decision", "module_order", "order", "purpose", "readings_note", "reflect_prompts", "routes", "show", "status", "teach", "title", "try_prompts", "type", "what_comes_out", "id", "created_date", "updated_date") values ('16', null, 'pending_approval', 'Entrepalooza Pilot 1 — Module Breakdown (Oct 5, 2026) · adopted Pilot 1 scope', 'Pilot 1 adopted card · lessons database copy Oct 6, 2026', 'No readiness judgment and no business direction implied. Moving on to Module 6 is optional. Every exit belongs: keep, change, test again, pause, stop, another direction, or keep looking.', '["M2-L3","M3-L3","M4-L3","M5-L2"]'::jsonb, 'M5-L3', '[]'::jsonb, 'Check one impression against evidence, choose a decision rule and protected boundary, and take stock of Modules 1–5 before the program turns outward in Module 6.', 35, true, 5, 3, 'Separate an impression from evidence, choose a decision rule and a boundary to protect, and take stock of what you want to keep from Modules 1–5.', null, '["What remains unknown? What information would change your mind?","What decision rule and boundary would you choose to keep?","Optional: What does this task ask of you (time, decisions, attention, interaction, uncertainty, resources, or effort)?","One piece of evidence you gathered:","One strategy, condition, or boundary worth keeping:","One support that mattered:","Optional: one question for later:","Optional, only if a pause or setback happened: what would make it workable to come back, and what would tell you not to? Coming back isn’t automatically preferred."]'::jsonb, '["Answer privately","Use the neutral example","Observe","Pass","Pause or stop","Add one note to your Life Map (or skip)"]'::jsonb, '#### Check an impression about this task

The statement “a shorter instruction must be easier” is an impression to examine. The paragraph and the checklist in Module 3 describe the same three-sentence reply.

You can compare their wording and layout directly. That comparison alone cannot establish which is easier for you. Your own experience may support, challenge, or leave the impression unanswered.

A bounded next question is “Does a checklist help me follow this task?” A limit can be an agreed amount of time, with permission to stop.', 'draft', 'The earlier lessons asked you to listen to how an activity is going and, if you chose, to protect what works or change one thing. This lesson is the stocktake. It is not another adjustment.

If you have an impression about your own try, start there. The statement about shorter instructions is a neutral example for practicing the distinction on this page.

An intuition is an impression or hunch. It can suggest a question, but it is not the same as evidence. Check what supports it, what challenges it, and what you do not yet know.

A decision rule states what information will guide your next choice. A protected boundary names a limit you want to keep. This is a halfway point. Modules 6–10 turn outward, but moving on is optional. No readiness judgment or business direction is implied. If you want, note one piece of evidence, one thing worth keeping, and one support from Modules 1–5. You can pass.

You can add one note to your Life Map if you want. Skipping is fine.', 'Check an impression and take stock', '["What impression or assumption, if any, do you want to check?","What can you actually observe that supports or challenges it?"]'::jsonb, 'next_decision', 'What you choose to keep from Modules 1–5: one piece of evidence, one thing worth keeping, one support, one Next Decision, and an optional question.', '6ad190ad65d36f46e5536061', '2026-10-16T02:49:17.310000'::timestamptz, '2026-10-20T03:21:03.139000'::timestamptz) on conflict (id) do update set "alias" = excluded."alias", "approval_note" = excluded."approval_note", "approval_state" = excluded."approval_state", "approved_source" = excluded."approved_source", "approved_version" = excluded."approved_version", "boundary" = excluded."boundary", "carry_forward" = excluded."carry_forward", "code" = excluded."code", "decision_options" = excluded."decision_options", "description" = excluded."description", "duration_min" = excluded."duration_min", "has_decision" = excluded."has_decision", "module_order" = excluded."module_order", "order" = excluded."order", "purpose" = excluded."purpose", "readings_note" = excluded."readings_note", "reflect_prompts" = excluded."reflect_prompts", "routes" = excluded."routes", "show" = excluded."show", "status" = excluded."status", "teach" = excluded."teach", "title" = excluded."title", "try_prompts" = excluded."try_prompts", "type" = excluded."type", "what_comes_out" = excluded."what_comes_out", "created_date" = excluded."created_date", "updated_date" = excluded."updated_date";
insert into public.admin_fields (entity, record_id, field, value) values ('Lesson', '6ad190ad65d36f46e5536061', 'internal_notes', '19 Oct 2026. The impression check now uses the reply example from Module 3. The Next Decision menu stays on this closing lesson.') on conflict (entity, record_id, field) do update set value = excluded.value;
insert into public.lesson ("alias", "approval_note", "approval_state", "approved_source", "approved_version", "boundary", "carry_forward", "code", "decision_options", "description", "duration_min", "has_decision", "module_order", "order", "purpose", "readings_note", "reflect_prompts", "routes", "show", "status", "teach", "title", "try_prompts", "type", "what_comes_out", "id", "created_date", "updated_date") values ('5', null, 'pending_approval', 'Entrepalooza Pilot 1 — Module Breakdown (Oct 5, 2026) · adopted Pilot 1 scope', 'Pilot 1 adopted card · lessons database copy Oct 6, 2026', 'Source draft: `06-module-1-facilitator-guide.md`. This is working curriculum content and remains in **Draft** until rehearsed. Keep participant choice, the right to pass, and facilitator boundaries intact.
Source pages (Ashley Zeck workspace): [‣](https://app.notion.com/p/b7a4e722bdf582f2b31781b8928c479e?pvs=21) · [‣](https://app.notion.com/p/a484e722bdf58371b7a381c08ebacb96?pvs=21)', '["M1-L1","M1-L3"]'::jsonb, 'M2-L1', '[]'::jsonb, 'A practical starting point for exploring an unfamiliar activity, asking someone about their work, or testing something you already find interesting.', 20, false, 2, 1, 'Explore a few real possibilities and choose one small experience you could try.', null, '[""]'::jsonb, '["Explore something unfamiliar","Follow something I''m already curious about","Observe or ask someone","Pass"]'::jsonb, '', 'draft', '## Find a possibility

You don''t need to begin with an idea. You can discover one through someone else''s work, a community activity, a skill demonstration, a local opportunity, or a subject you''ve never explored.

Here are a few places to look: work and trades; art and making; technology; community and volunteering; science and nature; entrepreneurship; or everyday problems you''d like to understand. These are starting categories, not choices you have to commit to.

## Make it real

Choose one accessible way to get closer: watch how something is done, speak with someone who does it, attend an introductory event, read a firsthand account, or try an appropriate beginner task. Keep it small enough to fit your time, money, responsibilities, and safety. You can choose observation if hands-on participation isn''t possible.

If you''d like another person''s perspective, the Module 1 Tribe Threads are a place to exchange discoveries. Posting is optional.

You don''t need to write a research plan. Just decide what you''d like to explore and a realistic way to encounter it.

## Choose how to begin

Bring an observation or uncertainty from Module 1, browse an unfamiliar possibility, or talk through the options with someone you choose. The starting cards include everyday activities, creativity, nature, community participation, and work. Each card has four ways in, and you can add your own.

Each card describes an encounter and what you need. Check practical access before planning a visit or conversation. Choosing a card records a starting point, not a completed experience. If it helps, use your learning agreement to choose the support and limits that make trying something workable.', 'Find Something to Try', '["What would you like to explore?","What is one practical way to encounter or try it?","What support or access would make it possible?","What time, cost, or safety limit should you respect?","","","","",""]'::jsonb, 'experiment', 'You have a possible experience to explore. You can do it before moving to the next lesson, or return when there''s an opportunity.', '6ad190ad65d36f46e553605f', '2026-10-16T02:49:17.309000'::timestamptz, '2026-10-24T07:55:28.523000'::timestamptz) on conflict (id) do update set "alias" = excluded."alias", "approval_note" = excluded."approval_note", "approval_state" = excluded."approval_state", "approved_source" = excluded."approved_source", "approved_version" = excluded."approved_version", "boundary" = excluded."boundary", "carry_forward" = excluded."carry_forward", "code" = excluded."code", "decision_options" = excluded."decision_options", "description" = excluded."description", "duration_min" = excluded."duration_min", "has_decision" = excluded."has_decision", "module_order" = excluded."module_order", "order" = excluded."order", "purpose" = excluded."purpose", "readings_note" = excluded."readings_note", "reflect_prompts" = excluded."reflect_prompts", "routes" = excluded."routes", "show" = excluded."show", "status" = excluded."status", "teach" = excluded."teach", "title" = excluded."title", "try_prompts" = excluded."try_prompts", "type" = excluded."type", "what_comes_out" = excluded."what_comes_out", "created_date" = excluded."created_date", "updated_date" = excluded."updated_date";
insert into public.admin_fields (entity, record_id, field, value) values ('Lesson', '6ad190ad65d36f46e553605f', 'internal_notes', 'Exposure menu is a labeled placeholder until the cohort, location, and partners are known; not delivery-ready.') on conflict (entity, record_id, field) do update set value = excluded.value;
insert into public.lesson ("alias", "approval_note", "approval_state", "approved_source", "approved_version", "boundary", "carry_forward", "code", "decision_options", "description", "duration_min", "has_decision", "module_order", "order", "purpose", "readings_note", "reflect_prompts", "routes", "show", "status", "teach", "title", "try_prompts", "type", "what_comes_out", "id", "created_date", "updated_date") values ('4.1', null, 'pending_approval', 'https://app.notion.com/p/3f1ca793c2c58113bc4fe7eb98824e19', 'Build Otherwise approval — 2026-10-09; expanded app reading revision — 2026-10-09', 'Don’t begin with a business idea, and don’t treat any conversation as validation. Nobody needs to share personal history to take part.', '["M5-L3"]'::jsonb, 'M6-L1', '[]'::jsonb, 'Choose one bounded question to investigate in the outside world. Start from a noticed problem, a skill or function, an interest or field, two possibilities to compare, an unanswered question from Module 5, or an honest unknown. No business idea is needed.', 25, false, 6, 1, 'Turn outward. Choose one bounded question (small enough to look into soon, with a clear edge) you can look into in the outside world — without needing a business idea, a solution, or a pitch.', null, '["Is this a question or a prediction? Is it small enough to look into soon?"]'::jsonb, '["Use a real question","Use the neutral example","Answer privately","Observe","Pass"]'::jsonb, '**Neutral demo (culinary):** “What does an accessible first exposure to culinary training actually involve?” is a field question. “I will love kitchen work” is a prediction — something to check later, not a starting fact.', 'draft', 'A good question for this module is small, points outward, and can be explored with what you can actually reach. You can come in through any of these routes. None ranks higher than another:

- a problem you noticed
- a skill or function you want to see in real use
- an interest or field
- two possibilities you want to compare
- an unanswered question from earlier modules
- an honest unknown (“I don’t know yet what to look at”)

Don’t begin with a business idea, and don’t treat any conversation as validation. Nobody needs to share personal history to take part. The question is the starting point. The evidence comes later.', 'Start with a question, not a pitch', '["Your bounded question:","Which route did you come in through?","How might you look into it?"]'::jsonb, 'activity', 'One bounded question and one proposed way to learn about it.', '6ad18c2d5550b97a5e042b20', '2026-10-16T02:30:05.275000'::timestamptz, '2026-10-16T02:30:05.275000'::timestamptz) on conflict (id) do update set "alias" = excluded."alias", "approval_note" = excluded."approval_note", "approval_state" = excluded."approval_state", "approved_source" = excluded."approved_source", "approved_version" = excluded."approved_version", "boundary" = excluded."boundary", "carry_forward" = excluded."carry_forward", "code" = excluded."code", "decision_options" = excluded."decision_options", "description" = excluded."description", "duration_min" = excluded."duration_min", "has_decision" = excluded."has_decision", "module_order" = excluded."module_order", "order" = excluded."order", "purpose" = excluded."purpose", "readings_note" = excluded."readings_note", "reflect_prompts" = excluded."reflect_prompts", "routes" = excluded."routes", "show" = excluded."show", "status" = excluded."status", "teach" = excluded."teach", "title" = excluded."title", "try_prompts" = excluded."try_prompts", "type" = excluded."type", "what_comes_out" = excluded."what_comes_out", "created_date" = excluded."created_date", "updated_date" = excluded."updated_date";
insert into public.admin_fields (entity, record_id, field, value) values ('Lesson', '6ad18c2d5550b97a5e042b20', 'internal_notes', 'Source: Notion Module 4 L1 (working replacement draft, Oct 6 2026). Loaded into app Module 6 per the 10-module crosswalk. Not approved for participant delivery.') on conflict (entity, record_id, field) do update set value = excluded.value;
insert into public.lesson ("alias", "approval_note", "approval_state", "approved_source", "approved_version", "boundary", "carry_forward", "code", "decision_options", "description", "duration_min", "has_decision", "module_order", "order", "purpose", "readings_note", "reflect_prompts", "routes", "show", "status", "teach", "title", "try_prompts", "type", "what_comes_out", "id", "created_date", "updated_date") values ('8.2', null, 'pending_approval', 'https://app.notion.com/p/360c0ceb904b4516b96e5e7245dfc71e', 'Build Otherwise approval — 2026-10-09; expanded app reading revision — 2026-10-09', 'No auto-enrollment. No required attendance or unpaid labor. No dependency framing: the group is not the only relationship or support. Leaving, muting, or unfollowing does not erase belonging.', '["M10-L1"]'::jsonb, 'M10-L2', '[]'::jsonb, 'Help design how this group stays in touch: how often, where, and with which practices.', 30, false, 10, 2, 'Help design a realistic way for the group to stay connected, without inventing services or requiring anyone to stay active.', null, '[]'::jsonb, '["Contribute ideas","Observe","Pass"]'::jsonb, '**Example:** “Monthly online check-in—proposed, no host confirmed” is honest. “Monthly check-in—available, with a confirmed host and channel” describes a different situation.', 'draft', 'Staying connected is optional. Possible ways include a shared channel, an occasional check-in, peer practice already started in earlier modules, or nothing formal.

Discuss only what is necessary to make options clear: how often, which channels exist, who maintains them, how someone pauses or leaves, and what is proposed versus what is already available. You do not have to join anything.

The Group Code still applies: ask before you share someone’s work, respect “no” and “not now,” and speak about actions and evidence rather than identities.', 'How we stay connected', '["How often would I want contact?","Which channel works for me?","What would still work during a new job or a quiet season?"]'::jsonb, 'activity', 'A draft **Tribe Continuity Map** that distinguishes proposed ideas from available commitments.', '6ad18c2d5550b97a5e042b2e', '2026-10-16T02:30:05.275000'::timestamptz, '2026-10-16T02:30:05.275000'::timestamptz) on conflict (id) do update set "alias" = excluded."alias", "approval_note" = excluded."approval_note", "approval_state" = excluded."approval_state", "approved_source" = excluded."approved_source", "approved_version" = excluded."approved_version", "boundary" = excluded."boundary", "carry_forward" = excluded."carry_forward", "code" = excluded."code", "decision_options" = excluded."decision_options", "description" = excluded."description", "duration_min" = excluded."duration_min", "has_decision" = excluded."has_decision", "module_order" = excluded."module_order", "order" = excluded."order", "purpose" = excluded."purpose", "readings_note" = excluded."readings_note", "reflect_prompts" = excluded."reflect_prompts", "routes" = excluded."routes", "show" = excluded."show", "status" = excluded."status", "teach" = excluded."teach", "title" = excluded."title", "try_prompts" = excluded."try_prompts", "type" = excluded."type", "what_comes_out" = excluded."what_comes_out", "created_date" = excluded."created_date", "updated_date" = excluded."updated_date";
insert into public.admin_fields (entity, record_id, field, value) values ('Lesson', '6ad18c2d5550b97a5e042b2e', 'internal_notes', 'Source: Notion Module 8 L2. Replaces the CUT ''Build the next-direction plan'' lesson.

FACILITATOR (moved from purpose): Discuss only what is necessary to make options clear: possible cadence, available channels, peer practices already seeded in Modules 0–9, who can maintain each element, what is proposed vs. available, how someone pauses, leaves, or changes their choice. Do not invent live mentor placements, staffed supports, or community promises before operations exist.') on conflict (entity, record_id, field) do update set value = excluded.value;
insert into public.lesson ("alias", "approval_note", "approval_state", "approved_source", "approved_version", "boundary", "carry_forward", "code", "decision_options", "description", "duration_min", "has_decision", "module_order", "order", "purpose", "readings_note", "reflect_prompts", "routes", "show", "status", "teach", "title", "try_prompts", "type", "what_comes_out", "id", "created_date", "updated_date") values ('4.3', null, 'pending_approval', 'https://app.notion.com/p/3f1ca793c2c581c1aa39fa170239e9d6', 'Build Otherwise approval — 2026-10-09; expanded app reading revision — 2026-10-09', 'Not every observed problem should become a business opportunity. Don''t present a learning conversation as formal research, treatment, employment or a promised solution. Don''t collect identifying or sensitive information without an approved process.', '["M6-L2"]'::jsonb, 'M6-L3', '[]'::jsonb, 'Pick one of three equal branches — pathway, problem/opportunity, or continued exploration — and look into it with that branch’s questions.', 30, false, 6, 3, 'Choose the branch that fits right now and look into it. (A branch is one of the three equal paths: pathway, problem/opportunity, or continued exploration.)', null, '["What surprised you? What did you assume that the evidence didn’t back up?"]'::jsonb, '["Pathway branch","Problem/opportunity branch","Continued-exploration branch","Observe","Pass"]'::jsonb, '**Culinary example:** Pathway branch — read the program page, note the schedule and fee, and watch a public demo video of a first-week class.', 'draft', 'A branch is one possible direction to investigate. You do not have to investigate every branch. You pick one (or more) that you can actually reach with the time, money, and access you have right now.

Investigation can mean looking something up, asking someone who does the work, watching a process, or trying a small bounded activity. It does not have to mean applying for a job, starting a business, or making a public commitment. You can also choose to pause a branch and return later.

Before you start, name what would count as useful information and what would make you stop or change the investigation.', 'Choose a branch and investigate', '["Pick a branch. Gather one or two pieces of evidence and label each with the six labels from the last lesson. Direct outreach stays optional; observation, public information, and supplied cases all count."]'::jsonb, 'experiment', 'One branch-specific evidence note and one open question.', '6ad18c2d5550b97a5e042b22', '2026-10-16T02:30:05.275000'::timestamptz, '2026-10-16T02:30:05.275000'::timestamptz) on conflict (id) do update set "alias" = excluded."alias", "approval_note" = excluded."approval_note", "approval_state" = excluded."approval_state", "approved_source" = excluded."approved_source", "approved_version" = excluded."approved_version", "boundary" = excluded."boundary", "carry_forward" = excluded."carry_forward", "code" = excluded."code", "decision_options" = excluded."decision_options", "description" = excluded."description", "duration_min" = excluded."duration_min", "has_decision" = excluded."has_decision", "module_order" = excluded."module_order", "order" = excluded."order", "purpose" = excluded."purpose", "readings_note" = excluded."readings_note", "reflect_prompts" = excluded."reflect_prompts", "routes" = excluded."routes", "show" = excluded."show", "status" = excluded."status", "teach" = excluded."teach", "title" = excluded."title", "try_prompts" = excluded."try_prompts", "type" = excluded."type", "what_comes_out" = excluded."what_comes_out", "created_date" = excluded."created_date", "updated_date" = excluded."updated_date";
insert into public.admin_fields (entity, record_id, field, value) values ('Lesson', '6ad18c2d5550b97a5e042b22', 'internal_notes', 'Source: Notion Module 4 L3.') on conflict (entity, record_id, field) do update set value = excluded.value;
insert into public.lesson ("alias", "approval_note", "approval_state", "approved_source", "approved_version", "boundary", "carry_forward", "code", "decision_options", "description", "duration_min", "has_decision", "module_order", "order", "purpose", "readings_note", "reflect_prompts", "routes", "show", "status", "teach", "title", "try_prompts", "type", "what_comes_out", "id", "created_date", "updated_date") values ('5.1', null, 'pending_approval', 'https://app.notion.com/p/3f1ca793c2c581188b5ee407c06bd281', 'Build Otherwise approval — 2026-10-09; expanded app reading revision — 2026-10-09', 'No payment, customer response, public exposure or second try is required.', '["M6-L4"]'::jsonb, 'M7-L1', '[]'::jsonb, 'Name one manageable try — Create, Practice, or Move forward — and write its type, what it should teach, its limit, and its stop rule before starting. An offer or invitation is optional.', 10, false, 7, 1, 'Name one manageable, bounded try: to Create, Practice, or Move forward.', null, '[]'::jsonb, '["Create","Practice","Move forward","Plan only","Pass"]'::jsonb, '**Example:** “Spend fifteen minutes making a paper sketch to see whether I enjoy arranging information” is more bounded than “Build a website.” It names an action, a learning question, and a time limit without requiring a finished product.', 'draft', 'A try is a small, bounded action you can do and then notice what happened. Naming the try means writing down what you will do, how long it will take, what would make you stop, and what you hope to learn.

The try does not have to be paid work, a customer conversation, or a public post. It can be a practice run, a conversation with one person, a short observation, or a bounded task you already do. No payment, customer response, or second try is required.

Write the stop or pause rule before you start. A try is not a commitment to keep going.', 'Name the try', '["What is the try?","What could it teach me?","What support, person, tool or information would help, if any?","What is its limit?","What would make me stop?"]'::jsonb, 'activity', 'A named try with its support, limit and stop rule.', '6ad18c2d5550b97a5e042b24', '2026-10-16T02:30:05.275000'::timestamptz, '2026-10-16T02:30:05.275000'::timestamptz) on conflict (id) do update set "alias" = excluded."alias", "approval_note" = excluded."approval_note", "approval_state" = excluded."approval_state", "approved_source" = excluded."approved_source", "approved_version" = excluded."approved_version", "boundary" = excluded."boundary", "carry_forward" = excluded."carry_forward", "code" = excluded."code", "decision_options" = excluded."decision_options", "description" = excluded."description", "duration_min" = excluded."duration_min", "has_decision" = excluded."has_decision", "module_order" = excluded."module_order", "order" = excluded."order", "purpose" = excluded."purpose", "readings_note" = excluded."readings_note", "reflect_prompts" = excluded."reflect_prompts", "routes" = excluded."routes", "show" = excluded."show", "status" = excluded."status", "teach" = excluded."teach", "title" = excluded."title", "try_prompts" = excluded."try_prompts", "type" = excluded."type", "what_comes_out" = excluded."what_comes_out", "created_date" = excluded."created_date", "updated_date" = excluded."updated_date";
insert into public.admin_fields (entity, record_id, field, value) values ('Lesson', '6ad18c2d5550b97a5e042b24', 'internal_notes', 'Source: Notion Module 5 module page only. The full M5 lesson pages were not in the upload, so teach/show are thin and the four try prompts come from the proposal''s summary of 5.1. Pull the full lesson text before rehearsal.') on conflict (entity, record_id, field) do update set value = excluded.value;
insert into public.lesson ("alias", "approval_note", "approval_state", "approved_source", "approved_version", "boundary", "carry_forward", "code", "decision_options", "description", "duration_min", "has_decision", "module_order", "order", "purpose", "readings_note", "reflect_prompts", "routes", "show", "status", "teach", "title", "try_prompts", "type", "what_comes_out", "id", "created_date", "updated_date") values ('6.2', null, 'pending_approval', 'https://app.notion.com/p/0778acb370f144a7b08c6c5671173829', 'Build Otherwise approval — 2026-10-09; expanded app reading revision — 2026-10-09', 'No “money mindset” diagnosis. No invasive household probing. No readiness score or investor-style math. Do not treat employment or pause as quitting.', '["M8-L1"]'::jsonb, 'M8-L2', '[]'::jsonb, 'Make labor and help visible, name constraints that aren''t about mindset, and set what you won''t put at risk.', 35, false, 8, 2, 'Make labor and support visible, name the constraints that are real for you, and set an affordability boundary without fake precision.', null, '["What actually fits around my real commitments?"]'::jsonb, '["Use my real case","Use a fictional case","Answer privately","Pass"]'::jsonb, '**Example:** A “free” workshop could still involve travel, childcare arrangements, two hours of attendance, and time afterward to recover. A borrowed tool may save money while requiring someone else’s time.', 'draft', 'Labor is the work the step requires — yours or someone else’s. Constraints are the real limits around that work: schedule, location, money on hand, tools, health, caregiving, transportation.

An affordability boundary is the limit you set for yourself before you start. It can be “I will not spend more than X,” “I will not miss this obligation,” or “I will stop if this takes more than Y hours.”

Name the labor and the constraints in plain language. Then set one affordability boundary you can actually keep. You can revise it later with new information.', 'Count labor, name real constraints, set an affordability boundary', '["Time and labor this took (or would take):","Help I had from others, paid or unpaid:","Constraints that are real (optional):","Which of those are mine to protect, and which are program or service barriers someone else could change?","I will not jeopardize…","I can risk up to…","Before repeating or expanding this, I need to know…","I would stop or change course if…"]'::jsonb, 'activity', 'A labor picture, an affordability boundary, and an optional list of constraints.', '6ad18c2d5550b97a5e042b28', '2026-10-16T02:30:05.275000'::timestamptz, '2026-10-16T02:30:05.275000'::timestamptz) on conflict (id) do update set "alias" = excluded."alias", "approval_note" = excluded."approval_note", "approval_state" = excluded."approval_state", "approved_source" = excluded."approved_source", "approved_version" = excluded."approved_version", "boundary" = excluded."boundary", "carry_forward" = excluded."carry_forward", "code" = excluded."code", "decision_options" = excluded."decision_options", "description" = excluded."description", "duration_min" = excluded."duration_min", "has_decision" = excluded."has_decision", "module_order" = excluded."module_order", "order" = excluded."order", "purpose" = excluded."purpose", "readings_note" = excluded."readings_note", "reflect_prompts" = excluded."reflect_prompts", "routes" = excluded."routes", "show" = excluded."show", "status" = excluded."status", "teach" = excluded."teach", "title" = excluded."title", "try_prompts" = excluded."try_prompts", "type" = excluded."type", "what_comes_out" = excluded."what_comes_out", "created_date" = excluded."created_date", "updated_date" = excluded."updated_date";
insert into public.admin_fields (entity, record_id, field, value) values ('Lesson', '6ad18c2d5550b97a5e042b28', 'internal_notes', 'Source: Notion Module 6 L2.

FACILITATOR: Only ask for information the decision actually needs; stop probing when it goes beyond that. Private and pass routes remain valid.') on conflict (entity, record_id, field) do update set value = excluded.value;
insert into public.lesson ("alias", "approval_note", "approval_state", "approved_source", "approved_version", "boundary", "carry_forward", "code", "decision_options", "description", "duration_min", "has_decision", "module_order", "order", "purpose", "readings_note", "reflect_prompts", "routes", "show", "status", "teach", "title", "try_prompts", "type", "what_comes_out", "id", "created_date", "updated_date") values ('7.2', null, 'pending_approval', 'https://app.notion.com/p/4b508de3dbd241699946f261ab350981', 'Build Otherwise approval — 2026-10-09; expanded app reading revision — 2026-10-09', 'Don’t steer toward or away from any direction. Do not treat employment, training, or pause as failure. No five-year vision, “discover your why,” or legacy requirement. No automatic alumni, mentor, or service role.', '["M8-L2","M8-L3","M9-L1"]'::jsonb, 'M9-L2', '[]'::jsonb, 'Choose one equal direction that fits the time, money, support and commitments you actually have.', 30, false, 9, 2, 'Choose a revisable direction that fits your current capacity and constraints, not a permanent identity.', null, '[]'::jsonb, '["Work / training","Project / venture / creative offer","Stabilize / pause / keep looking","Pass"]'::jsonb, '**Example:** “Explore a course while protecting my current shifts” names both a direction and a limit. “Pause while I check transport options” is also a direction decision. A structural barrier is not evidence that you lack purpose or commitment.', 'draft', 'A direction card is a plain statement of one possible next step that fits your current capacity. Capacity includes time, money, energy, access, and obligations you already have.

You can pick a card that says:

- Keep doing what I’m already doing
- Try one more small step in this direction
- Pause and rest
- Look at a different option
- Stop for now

The card is not a contract. It is a reminder of the choice you made with the information you have today.', 'Pick a direction card that fits your capacity', '["The card I’m choosing:","Evidence supporting this choice:","What it’s allowed to ask of me:","What it’s not allowed to cost:","What support or access condition it requires:","What is still unknown:"]'::jsonb, 'activity', 'A direction and explicit capacity protection.', '6ad18c2d5550b97a5e042b2b', '2026-10-16T02:30:05.275000'::timestamptz, '2026-10-16T02:30:05.275000'::timestamptz) on conflict (id) do update set "alias" = excluded."alias", "approval_note" = excluded."approval_note", "approval_state" = excluded."approval_state", "approved_source" = excluded."approved_source", "approved_version" = excluded."approved_version", "boundary" = excluded."boundary", "carry_forward" = excluded."carry_forward", "code" = excluded."code", "decision_options" = excluded."decision_options", "description" = excluded."description", "duration_min" = excluded."duration_min", "has_decision" = excluded."has_decision", "module_order" = excluded."module_order", "order" = excluded."order", "purpose" = excluded."purpose", "readings_note" = excluded."readings_note", "reflect_prompts" = excluded."reflect_prompts", "routes" = excluded."routes", "show" = excluded."show", "status" = excluded."status", "teach" = excluded."teach", "title" = excluded."title", "try_prompts" = excluded."try_prompts", "type" = excluded."type", "what_comes_out" = excluded."what_comes_out", "created_date" = excluded."created_date", "updated_date" = excluded."updated_date";
insert into public.admin_fields (entity, record_id, field, value) values ('Lesson', '6ad18c2d5550b97a5e042b2b', 'internal_notes', 'Source: Notion Module 7 L2. Notion relations for this lesson were self-referential; fixed here by order.') on conflict (entity, record_id, field) do update set value = excluded.value;
insert into public.lesson ("alias", "approval_note", "approval_state", "approved_source", "approved_version", "boundary", "carry_forward", "code", "decision_options", "description", "duration_min", "has_decision", "module_order", "order", "purpose", "readings_note", "reflect_prompts", "routes", "show", "status", "teach", "title", "try_prompts", "type", "what_comes_out", "id", "created_date", "updated_date") values ('7.3', null, 'pending_approval', 'https://app.notion.com/p/693e4a48cb63451885be901d047d6ad6', 'Build Otherwise approval — 2026-10-09; expanded app reading revision — 2026-10-09', 'No forced life mission or legacy statement. No duplicate Module 10 closing ceremony. No pressure to choose a project or venture. Participants may revise the direction later.', '["M9-L1","M9-L2"]'::jsonb, 'M9-L3', '[]'::jsonb, 'Set one next action, what it should teach you, and when you''ll review it.', 25, true, 9, 3, 'Turn your chosen direction and capacity protection into one visible, reviewable next decision.', null, '[]'::jsonb, '["Answer in full","Answer briefly","Answer privately","Pass"]'::jsonb, '**Example:** “I will check the current course timetable because schedule was the main barrier. I want to learn whether an accessible option exists. I will review the decision after I have that information.” This is smaller and more checkable than a five-year plan.', 'draft', 'Continuity means you know what you will do next and when you will check it. It does not mean you have to keep going in the same direction.

Set one next decision using the same words as the rest of the program: Keep, Change, Test again, Pause, Stop, Another direction, Keep looking. Add the reason, the next action, and the review date. “I don’t know yet” is allowed.

You choose how much of this stays private and who, if anyone, sees it.', 'Set the next decision for continuity', '["Next action:","Why this:","What it should teach me:","What I won’t allow it to cost:","Review date or condition:"]'::jsonb, 'next_decision', 'A Current Direction Record: the evidence you used, your direction card, what it may ask and must not cost, one next action and what it should teach, a review point, and your Next Decision. It can carry into Module 10.', '6ad18c2d5550b97a5e042b2c', '2026-10-16T02:30:05.275000'::timestamptz, '2026-10-16T02:30:05.275000'::timestamptz) on conflict (id) do update set "alias" = excluded."alias", "approval_note" = excluded."approval_note", "approval_state" = excluded."approval_state", "approved_source" = excluded."approved_source", "approved_version" = excluded."approved_version", "boundary" = excluded."boundary", "carry_forward" = excluded."carry_forward", "code" = excluded."code", "decision_options" = excluded."decision_options", "description" = excluded."description", "duration_min" = excluded."duration_min", "has_decision" = excluded."has_decision", "module_order" = excluded."module_order", "order" = excluded."order", "purpose" = excluded."purpose", "readings_note" = excluded."readings_note", "reflect_prompts" = excluded."reflect_prompts", "routes" = excluded."routes", "show" = excluded."show", "status" = excluded."status", "teach" = excluded."teach", "title" = excluded."title", "try_prompts" = excluded."try_prompts", "type" = excluded."type", "what_comes_out" = excluded."what_comes_out", "created_date" = excluded."created_date", "updated_date" = excluded."updated_date";
insert into public.admin_fields (entity, record_id, field, value) values ('Lesson', '6ad18c2d5550b97a5e042b2c', 'internal_notes', 'Source: Notion Module 7 L3.') on conflict (entity, record_id, field) do update set value = excluded.value;
insert into public.lesson ("alias", "approval_note", "approval_state", "approved_source", "approved_version", "boundary", "carry_forward", "code", "decision_options", "description", "duration_min", "has_decision", "module_order", "order", "purpose", "readings_note", "reflect_prompts", "routes", "show", "status", "teach", "title", "try_prompts", "type", "what_comes_out", "id", "created_date", "updated_date") values ('8', null, 'pending_approval', 'Entrepalooza Pilot 1 — Module Breakdown (Oct 5, 2026) · adopted Pilot 1 scope', 'Pilot 1 adopted card · lessons database copy Oct 6, 2026', 'A single attempt does not establish a personality type or a permanent preference. Personal work stays optional, and adverse conditions are never manufactured.', '["M2-L1","M2-L2","M2-L3"]'::jsonb, 'M3-L1', '[]'::jsonb, 'Start with a recent experience or ordinary task. Separate observation from self-description and identify one operating condition worth testing.', 20, false, 3, 1, 'Describe one part of a task''s setup and turn it into a question you could test.', null, '["What did you observe about starting, continuing, or stopping? What is still an interpretation?","What would you like to find out about one condition? “I don’t know yet” is valid."]'::jsonb, '["Use my Module 2 encounter","Use an everyday task","Use the reply example","Reflect privately","Observe","Pass"]'::jsonb, '#### The same reply, two setups

The task is a three-sentence reply: say you got the message, name one thing you can do, and name when.

Paragraph instructions: Read the message, write three sentences that confirm you received it, name one thing you can do, and say when, then reread to check that all three parts are there.

Checklist instructions:
1. Say you got the message.
2. Name one thing you can do.
3. Say when.

The task stays the same. The instruction format changes. That format is an operating condition. You can write the reply or only look at the two setups. If you have an encounter from Module 2, use that instead. Any ordinary task from this week works too.', 'draft', 'Start with the encounter you already recorded in Module 2, if you have one. Bring that record into this step. An ordinary task from this week is the next place to look. The reply example below shows how to name a setup when you do not have your own task yet. It is a demonstration, not the assignment.

An operating condition is part of the setup in which you do a task — not a type of person. It can include how clear the instructions are, how much choice you have, noise, whether you work alone or with someone, how much is uncertain, and the time available.

The same task can feel different when its setup changes. You’re learning to describe one condition and ask what it changes for this task. A single attempt does not establish a personality type or a permanent preference. An observation describes what happened. An interpretation is your explanation of it. Keep those separate. “I don’t know what helped” is a valid starting point.', 'Understand the setup around a task', '["Start with the encounter you brought from Module 2, if you have one. If you do not, use an ordinary task from this week. Use the reply example only when neither is available. You can also leave this blank.","What part of its setup can you actually describe—for example, instructions, noise, company, choice, or available time?"]'::jsonb, 'activity', 'One task, one observed condition, and a question or honest unknown.', '6ad18c2d5550b97a5e042b17', '2026-10-16T02:30:05.275000'::timestamptz, '2026-10-20T01:39:49.698000'::timestamptz) on conflict (id) do update set "alias" = excluded."alias", "approval_note" = excluded."approval_note", "approval_state" = excluded."approval_state", "approved_source" = excluded."approved_source", "approved_version" = excluded."approved_version", "boundary" = excluded."boundary", "carry_forward" = excluded."carry_forward", "code" = excluded."code", "decision_options" = excluded."decision_options", "description" = excluded."description", "duration_min" = excluded."duration_min", "has_decision" = excluded."has_decision", "module_order" = excluded."module_order", "order" = excluded."order", "purpose" = excluded."purpose", "readings_note" = excluded."readings_note", "reflect_prompts" = excluded."reflect_prompts", "routes" = excluded."routes", "show" = excluded."show", "status" = excluded."status", "teach" = excluded."teach", "title" = excluded."title", "try_prompts" = excluded."try_prompts", "type" = excluded."type", "what_comes_out" = excluded."what_comes_out", "created_date" = excluded."created_date", "updated_date" = excluded."updated_date";
insert into public.admin_fields (entity, record_id, field, value) values ('Lesson', '6ad18c2d5550b97a5e042b17', 'internal_notes', '19 Oct 2026. The word-sorting demonstration was retired. The on-page example is a three-sentence reply in two instruction formats. Prefer the Module 2 encounter when the person has one. The Next Decision menu is withheld until M3-L3.') on conflict (entity, record_id, field) do update set value = excluded.value;
insert into public.lesson ("alias", "approval_note", "approval_state", "approved_source", "approved_version", "boundary", "carry_forward", "code", "decision_options", "description", "duration_min", "has_decision", "module_order", "order", "purpose", "readings_note", "reflect_prompts", "routes", "show", "status", "teach", "title", "try_prompts", "type", "what_comes_out", "id", "created_date", "updated_date") values ('9', null, 'pending_approval', 'Entrepalooza Pilot 1 — Module Breakdown (Oct 5, 2026) · adopted Pilot 1 scope', 'Pilot 1 adopted card · lessons database copy Oct 6, 2026', 'Do not add pressure, deprivation, public performance or distress to create a comparison. One attempt can raise a useful question; it cannot prove that the change caused the result. A safe plan without an attempt remains valid.', '["M3-L1","M2-L2"]'::jsonb, 'M3-L2', '[]'::jsonb, 'Design and attempt one safe, bounded change to the task conditions, then record the result and immediate cost.', 30, false, 3, 2, 'Plan or attempt one reversible change, and notice both the result and the effort it takes.', null, '["What actually happened, or why was it not tried? No opportunity is a valid result.","What effort or discomfort did it take, including afterward?","What might you try again, and what evidence would make you revise your conclusion?"]'::jsonb, '["Attempt it","Plan only","Attempt it with support or an adaptation","Observe","Pass"]'::jsonb, '#### Use the reply to plan a comparison

Task: a three-sentence reply that says you got the message, names one thing you can do, and names when. Condition to compare: paragraph instructions and checklist instructions.

Keep the same reply and the same agreed amount of time. You can write it or only look. Record which format you used and what actually happened. No result is supplied here.

If you do the reply twice, the second time is easier because you already know what you want to say. That familiarity is another possible explanation for any difference. You can plan the comparison without doing it. Your Module 2 encounter, or an ordinary task from this week, can be the task instead.', 'draft', 'Change one part of the setup around the task you named in the last lesson, or around the encounter you brought from Module 2. The reply example shows the shape of a comparison when you are planning only, or when you do not have your own task yet.

A changed-condition test means trying one manageable adjustment around a task while keeping the task and amount of work as similar as practical. Choose a time limit and a stop rule before you start. A stop rule is a condition that tells you to end or change the activity.

One attempt can raise a useful question. It cannot prove that the change caused the result. Practice, familiarity, and other differences may also matter. You can plan the comparison without running it. Planning only is a complete route.', 'Try changing one part of the setup', '["What single part of the setup would you change?","What task and amount of time will stay similar? What else might differ?","What time limit, support, and stop rule would make the attempt workable? You can choose to plan only.","What would show that this was easier to start, easier to adjust, or easier to stop? You do not need to judge how intense it felt."]'::jsonb, 'experiment', 'A bounded test plan, an actual result or non-attempt, cost, and a revisable conclusion.', '6ad18c2d5550b97a5e042b18', '2026-10-16T02:30:05.275000'::timestamptz, '2026-10-20T01:39:49.980000'::timestamptz) on conflict (id) do update set "alias" = excluded."alias", "approval_note" = excluded."approval_note", "approval_state" = excluded."approval_state", "approved_source" = excluded."approved_source", "approved_version" = excluded."approved_version", "boundary" = excluded."boundary", "carry_forward" = excluded."carry_forward", "code" = excluded."code", "decision_options" = excluded."decision_options", "description" = excluded."description", "duration_min" = excluded."duration_min", "has_decision" = excluded."has_decision", "module_order" = excluded."module_order", "order" = excluded."order", "purpose" = excluded."purpose", "readings_note" = excluded."readings_note", "reflect_prompts" = excluded."reflect_prompts", "routes" = excluded."routes", "show" = excluded."show", "status" = excluded."status", "teach" = excluded."teach", "title" = excluded."title", "try_prompts" = excluded."try_prompts", "type" = excluded."type", "what_comes_out" = excluded."what_comes_out", "created_date" = excluded."created_date", "updated_date" = excluded."updated_date";
insert into public.admin_fields (entity, record_id, field, value) values ('Lesson', '6ad18c2d5550b97a5e042b18', 'internal_notes', '19 Oct 2026. Comparison example is the three-sentence reply, not the word-sorting task. Planning only remains a complete route. The Next Decision menu is withheld until M3-L3.') on conflict (entity, record_id, field) do update set value = excluded.value;
insert into public.lesson ("alias", "approval_note", "approval_state", "approved_source", "approved_version", "boundary", "carry_forward", "code", "decision_options", "description", "duration_min", "has_decision", "module_order", "order", "purpose", "readings_note", "reflect_prompts", "routes", "show", "status", "teach", "title", "try_prompts", "type", "what_comes_out", "id", "created_date", "updated_date") values ('4.2', null, 'pending_approval', 'https://app.notion.com/p/3f1ca793c2c5815fb030e13682737626', 'Build Otherwise approval — 2026-10-09; expanded app reading revision — 2026-10-09', 'Ask permission before taking notes, quoting, recording or sharing. Don''t ask anyone for trauma stories, unpaid emotional labor or free consulting. No, no response and limited access are real outcomes.', '["M6-L1"]'::jsonb, 'M6-L2', '[]'::jsonb, 'Gather a small amount of accessible outside evidence and sort it with six labels. A 60-second teach-back checks that the labels make sense before anyone picks a branch.', 30, false, 6, 2, 'Gather a little outside evidence and sort it honestly, so the next choice rests on what you actually found.', null, '["Which label was hardest to tell apart? What did you almost call an observation that was really an assumption?"]'::jsonb, '["Use a real question","Use the neutral example","Answer privately","Use an approved simulation","Pass"]'::jsonb, '**Culinary example:**  
“I watched the program’s public class video: students practiced knife cuts at shared stations” (direct observation).  
“The posted class schedule runs 6–10 AM” (existing information).  
“A friend said the instructor is patient” (secondhand report).  
“I’d be fine with early mornings” (assumption).  
“I don’t know whether there’s a payment plan” (uncertainty).', 'draft', 'Outside evidence is information you can check that did not come only from your own mind. It can be something you saw, something someone else reported, or something already written down.

Six plain labels help you sort what you gather:

- Direct observation: something you saw or experienced yourself
- Secondhand report: something someone else told you
- Existing information: something already published or recorded
- Assumption: something you believe but have not yet checked
- Conclusion: a judgment you have already made
- Uncertainty: what you do not yet know

Labeling is not scoring. An assumption can still be useful. Uncertainty can stay. The point is to know which kind of information you have before you decide what to do with it.', 'Gather and sort outside evidence', '["60-second teach-back: using the culinary example, name one observation, one assumption, and one uncertainty.","Gather one small piece of accessible evidence for your own question (observation, public information, a supplied case, or a comfortable conversation). What is it, and which label fits?"]'::jsonb, 'activity', 'At least one sorted piece of outside information and one remaining uncertainty.', '6ad18c2d5550b97a5e042b21', '2026-10-16T02:30:05.275000'::timestamptz, '2026-10-16T02:30:05.275000'::timestamptz) on conflict (id) do update set "alias" = excluded."alias", "approval_note" = excluded."approval_note", "approval_state" = excluded."approval_state", "approved_source" = excluded."approved_source", "approved_version" = excluded."approved_version", "boundary" = excluded."boundary", "carry_forward" = excluded."carry_forward", "code" = excluded."code", "decision_options" = excluded."decision_options", "description" = excluded."description", "duration_min" = excluded."duration_min", "has_decision" = excluded."has_decision", "module_order" = excluded."module_order", "order" = excluded."order", "purpose" = excluded."purpose", "readings_note" = excluded."readings_note", "reflect_prompts" = excluded."reflect_prompts", "routes" = excluded."routes", "show" = excluded."show", "status" = excluded."status", "teach" = excluded."teach", "title" = excluded."title", "try_prompts" = excluded."try_prompts", "type" = excluded."type", "what_comes_out" = excluded."what_comes_out", "created_date" = excluded."created_date", "updated_date" = excluded."updated_date";
insert into public.admin_fields (entity, record_id, field, value) values ('Lesson', '6ad18c2d5550b97a5e042b21', 'internal_notes', 'Source: Notion Module 4 L2. Oct 9, 2026: the ''evening attendance listed'' line was relabeled as existing information, and a program-authored direct observation (watching a public class video) was added so the teach-back has a real observation to find.') on conflict (entity, record_id, field) do update set value = excluded.value;
insert into public.lesson ("alias", "approval_note", "approval_state", "approved_source", "approved_version", "boundary", "carry_forward", "code", "decision_options", "description", "duration_min", "has_decision", "module_order", "order", "purpose", "readings_note", "reflect_prompts", "routes", "show", "status", "teach", "title", "try_prompts", "type", "what_comes_out", "id", "created_date", "updated_date") values ('5.3', null, 'pending_approval', 'https://app.notion.com/p/3f1ca793c2c5819f9cecee090e12e800', 'Build Otherwise approval — 2026-10-09; expanded app reading revision — 2026-10-09', 'Keep looking counts as a full decision on its own; it doesn''t need extra justification.', '["M7-L1","M7-L2"]'::jsonb, 'M7-L3', '[]'::jsonb, 'Write what the try taught, what it cost, and what is still unknown; optionally rate enjoyment and goal/accomplishment separately; choose one of seven Next Decisions.', 15, true, 7, 3, 'Name what the try taught, what it cost, and what is still unknown, then decide what''s next.', null, '[]'::jsonb, '["Plain words","Optional ratings","Observe","Pass"]'::jsonb, '**Example:** “I enjoyed arranging the pieces, needed help with the instructions, and felt tired afterward” gives you more to work with than “It went well.”', 'draft', 'Notice what the try taught. Keep the report separate from the interpretation.

- What happened?
- What did it cost (time, effort, money, energy)?
- What surprised you?
- What is still unclear?

You do not have to decide whether the try “worked.” A clear observation and an unanswered question are enough. You choose what to carry forward and what stays private.', 'Notice what the try taught', '["What did it teach?","What did it cost?","What is still unknown?"]'::jsonb, 'reflection', 'A named try, what it taught, what it cost, what is still unknown, and one Next Decision.', '6ad18c2d5550b97a5e042b26', '2026-10-16T02:30:05.275000'::timestamptz, '2026-10-16T02:30:05.275000'::timestamptz) on conflict (id) do update set "alias" = excluded."alias", "approval_note" = excluded."approval_note", "approval_state" = excluded."approval_state", "approved_source" = excluded."approved_source", "approved_version" = excluded."approved_version", "boundary" = excluded."boundary", "carry_forward" = excluded."carry_forward", "code" = excluded."code", "decision_options" = excluded."decision_options", "description" = excluded."description", "duration_min" = excluded."duration_min", "has_decision" = excluded."has_decision", "module_order" = excluded."module_order", "order" = excluded."order", "purpose" = excluded."purpose", "readings_note" = excluded."readings_note", "reflect_prompts" = excluded."reflect_prompts", "routes" = excluded."routes", "show" = excluded."show", "status" = excluded."status", "teach" = excluded."teach", "title" = excluded."title", "try_prompts" = excluded."try_prompts", "type" = excluded."type", "what_comes_out" = excluded."what_comes_out", "created_date" = excluded."created_date", "updated_date" = excluded."updated_date";
insert into public.admin_fields (entity, record_id, field, value) values ('Lesson', '6ad18c2d5550b97a5e042b26', 'internal_notes', 'Source: Notion Module 5 module page + proposal notes on 5.3 (Murphy 2026 is a substance-use intervention source; don''t cite it as nonclinical validation for the ratings).') on conflict (entity, record_id, field) do update set value = excluded.value;
insert into public.lesson ("alias", "approval_note", "approval_state", "approved_source", "approved_version", "boundary", "carry_forward", "code", "decision_options", "description", "duration_min", "has_decision", "module_order", "order", "purpose", "readings_note", "reflect_prompts", "routes", "show", "status", "teach", "title", "try_prompts", "type", "what_comes_out", "id", "created_date", "updated_date") values ('6.1', null, 'pending_approval', 'https://app.notion.com/p/65d1c986af364f75935b6aa874392a9d', 'Build Otherwise approval — 2026-10-09; expanded app reading revision — 2026-10-09', 'No bank statements, debt lists, household disclosure, forecasts, or funding plans. No pressure to spend, borrow, fundraise, sell, or repeat the Module 7 try. This is financial education, not financial, tax, debt, or benefits advice.', '["M7-L3"]'::jsonb, 'M8-L1', '[]'::jsonb, 'Make the money side of a try or next step visible, including $0, without turning it into a business plan.', 35, false, 8, 1, 'Turn the cost and resource reality of your Module 7 try, or a fictional case, into an honest cost map. A $0 map, plan-only completion, non-offer try, or employment-bound decision all count.', null, '["What did I forget to count, and what surprised me?"]'::jsonb, '["Use a real try or next step","Use a $0 or plan-only case","Use a fictional case","Answer privately","Pass"]'::jsonb, 'A try produced $0. It used scrap paper and an already-owned pen, plus setup time that was initially forgotten. That is still a complete, honest starting map.', 'draft', 'Cost is what a try or next step actually takes. It can be money, time, transit, childcare, tools, help from other people, or energy you need afterward.

Map the costs you can see right now. Do not estimate income or promise future earnings. The goal is to see the real cost of the step in front of you, not to build a business plan.

Unknown costs are allowed to stay unknown. Name them so you can look at them later if you choose.', 'Map what this try or next step actually cost', '["Money spent:","Money received:","Money kept (what’s left after costs, which isn’t the same as what came in):","Resources already owned:","Resources borrowed or shared:","Costs or labor you didn’t count at first (like time, rides, childcare, or energy):","What stays private?"]'::jsonb, 'activity', 'Inputs toward your Financial Reality Note: the try or next step, what was spent, received, owned, and borrowed, and any labor or cost still unknown.', '6ad18c2d5550b97a5e042b27', '2026-10-16T02:30:05.275000'::timestamptz, '2026-10-16T02:30:05.275000'::timestamptz) on conflict (id) do update set "alias" = excluded."alias", "approval_note" = excluded."approval_note", "approval_state" = excluded."approval_state", "approved_source" = excluded."approved_source", "approved_version" = excluded."approved_version", "boundary" = excluded."boundary", "carry_forward" = excluded."carry_forward", "code" = excluded."code", "decision_options" = excluded."decision_options", "description" = excluded."description", "duration_min" = excluded."duration_min", "has_decision" = excluded."has_decision", "module_order" = excluded."module_order", "order" = excluded."order", "purpose" = excluded."purpose", "readings_note" = excluded."readings_note", "reflect_prompts" = excluded."reflect_prompts", "routes" = excluded."routes", "show" = excluded."show", "status" = excluded."status", "teach" = excluded."teach", "title" = excluded."title", "try_prompts" = excluded."try_prompts", "type" = excluded."type", "what_comes_out" = excluded."what_comes_out", "created_date" = excluded."created_date", "updated_date" = excluded."updated_date";
insert into public.admin_fields (entity, record_id, field, value) values ('Lesson', '6ad18c2d5550b97a5e042b27', 'internal_notes', 'Source: Notion Module 6 L1. Non-zero worked example added Oct 9, 2026 (program-authored neutral case) so money-in vs money-kept is actually shown; the original $0 demo is kept as the second paragraph. Pathway, project/offer and pause entries are all valid; employment-bound decisions count.') on conflict (entity, record_id, field) do update set value = excluded.value;
insert into public.lesson ("alias", "approval_note", "approval_state", "approved_source", "approved_version", "boundary", "carry_forward", "code", "decision_options", "description", "duration_min", "has_decision", "module_order", "order", "purpose", "readings_note", "reflect_prompts", "routes", "show", "status", "teach", "title", "try_prompts", "type", "what_comes_out", "id", "created_date", "updated_date") values ('7.1', null, 'pending_approval', 'https://app.notion.com/p/7087ff43eeff433496a24b6f01d8529f', 'Build Otherwise approval — 2026-10-09; expanded app reading revision — 2026-10-09', 'No purpose diagnosis, destiny claim, or profundity requirement. No trauma disclosure to “find meaning.” Keep poverty, access, and other structural barriers visible. Employment, stabilization, and “still don’t know” remain complete paths.', '["M7-L3","M8-L3"]'::jsonb, 'M9-L1', '[]'::jsonb, 'Look back at what you actually tried and learned, and write what success means for you right now.', 35, false, 9, 1, 'Review existing evidence without inventing a destiny story, then define what success means now.', null, '["Is there a ''should'' hiding in my success-now statement?"]'::jsonb, '["Use my records","Use the neutral example","Answer privately","Pass"]'::jsonb, 'An entry definition, “Launch something of my own,” may become: “Know whether this question is worth another bounded try without missing rent.” Neither statement is wrong. The second is evidence-updated, not a permanent identity.', 'draft', 'Success-now is what counts as useful at this moment, given the evidence you have and the capacity you have. It is not a permanent definition of success.

Review what you actually observed across the pilot. Keep the evidence separate from the story. Then write a short statement of what success looks like for you right now. You can revise it later.

“I don’t know yet” is a complete answer. You do not need a career plan or a business goal to finish this step.', 'Review the evidence and redefine success-now', '["What I thought:","What I tried:","What happened:","What I learned:","What changed:","Success for me right now means…","I am no longer requiring myself to…","The evidence I am using is…","I still do not know…"]'::jsonb, 'reflection', 'A success-now note and a short list of unknowns.', '6ad18c2d5550b97a5e042b2a', '2026-10-16T02:30:05.275000'::timestamptz, '2026-10-16T02:30:05.275000'::timestamptz) on conflict (id) do update set "alias" = excluded."alias", "approval_note" = excluded."approval_note", "approval_state" = excluded."approval_state", "approved_source" = excluded."approved_source", "approved_version" = excluded."approved_version", "boundary" = excluded."boundary", "carry_forward" = excluded."carry_forward", "code" = excluded."code", "decision_options" = excluded."decision_options", "description" = excluded."description", "duration_min" = excluded."duration_min", "has_decision" = excluded."has_decision", "module_order" = excluded."module_order", "order" = excluded."order", "purpose" = excluded."purpose", "readings_note" = excluded."readings_note", "reflect_prompts" = excluded."reflect_prompts", "routes" = excluded."routes", "show" = excluded."show", "status" = excluded."status", "teach" = excluded."teach", "title" = excluded."title", "try_prompts" = excluded."try_prompts", "type" = excluded."type", "what_comes_out" = excluded."what_comes_out", "created_date" = excluded."created_date", "updated_date" = excluded."updated_date";
insert into public.admin_fields (entity, record_id, field, value) values ('Lesson', '6ad18c2d5550b97a5e042b2a', 'internal_notes', 'Source: Notion Module 7 L1. Proposal: passion/inspiration/purpose/success distinctions need more teaching before they''re asked for. Proposed optional home for the Sheldon motivation reflection (pending attribution/permission check).') on conflict (entity, record_id, field) do update set value = excluded.value;
insert into public.lesson ("alias", "approval_note", "approval_state", "approved_source", "approved_version", "boundary", "carry_forward", "code", "decision_options", "description", "duration_min", "has_decision", "module_order", "order", "purpose", "readings_note", "reflect_prompts", "routes", "show", "status", "teach", "title", "try_prompts", "type", "what_comes_out", "id", "created_date", "updated_date") values ('15', null, 'pending_approval', 'Entrepalooza Pilot 1 — Module Breakdown (Oct 5, 2026) · adopted Pilot 1 scope', 'Pilot 1 adopted card · lessons database copy Oct 6, 2026', 'Use natural opportunities only: no episode quota, daily log, or manufactured urgency. A change after a strategy does not prove the strategy caused it. Both routes are equal, and ''harmonious engagement achieved'' is never scored. Stopping or redirecting is never a failure.', '["M5-L1","M2-L2","M2-L3"]'::jsonb, 'M5-L2', '[]'::jsonb, 'Two equal routes. Keep what is in tune: name what supports choice and flexibility and protect one working condition. Or change one thing: choose one low-risk response, try it during an ordinary task if you want, and record what happened next.', 40, false, 5, 2, 'Protect a setup that is already working, or change one thing and look at what happened next.', null, '["What actually happened next, or why was it not attempted?","Was the next choice easier, harder, unchanged, or unclear?","What effort, discomfort, or later effect did you notice? What else might explain the result?"]'::jsonb, '["Keep what is in tune","Change one thing","Observe","Pass","Pause or stop"]'::jsonb, '#### Clarify a reading task

The task available here is to identify the five labels from the previous lesson. A small response is to write the next action: “Find and underline the five labels.”

You can check the result against the words signal, story, urge, usual action, cost. No emotional result is assumed.

If you try this, record whether the next action became clearer, stayed unclear, or was not attempted. Observe only is equally available.', 'draft', 'This is the adjustment, if you want one. You have already listened. Now you either protect a setup that is already working, or you change one thing. Both count the same. You are not fixing yourself.

Use an activity you have actually been in when you have one. The reading-task example shows how to name a next action. It is the demonstration, not a substitute for your own activity.

There are two equal routes. Keeping what is in tune means noticing a condition that already supports chosen, flexible engagement and protecting it. Changing one thing means trying one small, reversible response during an ordinary task and recording what happened next.

You do not need a setback or a crisis to have something useful to learn. A useful next choice might mean understanding a limit or deciding to stop. It does not have to mean becoming calm. Use natural opportunities only. A change after a response does not prove the response caused it. Stopping or redirecting is not failure.', 'Keep what is in tune, or change one thing', '["Keep what is in tune: What one condition is working, and how will you protect it this week? Will you continue, deepen, or repeat it?","Change one thing: What one small response, if any, would you like to try?","Change one thing: What would a useful next choice look like?","Change one thing: What duration, support, and stop rule will guide the attempt? You may plan only."]'::jsonb, 'activity', 'Either one protected working condition, or one small change with an actual observation or a non-attempt, its cost, and a next decision.', '6ad18c2d5550b97a5e042b1e', '2026-10-16T02:30:05.275000'::timestamptz, '2026-10-20T03:21:48.320000'::timestamptz) on conflict (id) do update set "alias" = excluded."alias", "approval_note" = excluded."approval_note", "approval_state" = excluded."approval_state", "approved_source" = excluded."approved_source", "approved_version" = excluded."approved_version", "boundary" = excluded."boundary", "carry_forward" = excluded."carry_forward", "code" = excluded."code", "decision_options" = excluded."decision_options", "description" = excluded."description", "duration_min" = excluded."duration_min", "has_decision" = excluded."has_decision", "module_order" = excluded."module_order", "order" = excluded."order", "purpose" = excluded."purpose", "readings_note" = excluded."readings_note", "reflect_prompts" = excluded."reflect_prompts", "routes" = excluded."routes", "show" = excluded."show", "status" = excluded."status", "teach" = excluded."teach", "title" = excluded."title", "try_prompts" = excluded."try_prompts", "type" = excluded."type", "what_comes_out" = excluded."what_comes_out", "created_date" = excluded."created_date", "updated_date" = excluded."updated_date";
insert into public.admin_fields (entity, record_id, field, value) values ('Lesson', '6ad18c2d5550b97a5e042b1e', 'internal_notes', '19 Oct 2026. The two equal routes stay the activity. 20 Oct 2026. Participant labels are "Keep what is in tune" and "Change one thing." The eight Next Decision words stay withheld here and are offered at M5-L3. The module frame is tuning your instrument. This lesson is the optional adjustment. The person is not the instrument.') on conflict (entity, record_id, field) do update set value = excluded.value;
insert into public.lesson ("alias", "approval_note", "approval_state", "approved_source", "approved_version", "boundary", "carry_forward", "code", "decision_options", "description", "duration_min", "has_decision", "module_order", "order", "purpose", "readings_note", "reflect_prompts", "routes", "show", "status", "teach", "title", "try_prompts", "type", "what_comes_out", "id", "created_date", "updated_date") values ('12', null, 'pending_approval', 'Entrepalooza Pilot 1 — Module Breakdown (Oct 5, 2026) · adopted Pilot 1 scope', 'Pilot 1 adopted card · lessons database copy Oct 6, 2026', 'All of these count as capability evidence: showing up, asking for help, using an accommodation or support, honoring a boundary, stopping at a stop rule, partly completing something, revising a plan, returning after a pause, repairing something, and choosing not to continue. Support, accommodation and collaboration do not make the evidence less valid. No forced pledge, confession, public apology or real contact is required.', '["M4-L1","M2-L2"]'::jsonb, 'M4-L2', '[]'::jsonb, 'Use one small, observable action as evidence about the statement you kept separate from a verdict.', 30, false, 4, 2, 'Use one small, observable action as evidence about the statement you kept separate from a verdict.', null, '["How will you tell what actually happened rather than just what you intended?","What will you record if there is no opportunity or you choose not to try?","What might the usual response or planned action cost?"]'::jsonb, '["Use an action from my own week","Use the accuracy example on this page","Reflect privately","Observe","Pass"]'::jsonb, '#### An action you can observe on this page

Observable practice: reread one sentence and identify the words you are using as evidence.

If a value would help you choose that action, accuracy is one you could use. A standard for this task would be: check what is printed before deciding what it says. You do not need the value to do the action. This does not establish a lifelong value.

#### Another example: respect

Observable practice: before offering help, ask, “Would you like feedback, help, or just someone to listen?”

If a value would help, respect is one you could use. A standard would be: ask before giving advice. The question you can observe is the evidence.', 'draft', 'This practice gathers evidence about the statement you separated from a verdict in the last lesson. It is not an exercise in becoming a better person.

If a standard would help you choose the action, use one. A value is something that matters to you. A standard is what that value asks of you in a particular situation. A practice is the small action you can actually observe. The action is the evidence. You do not need a value statement to finish this lesson.

A pressure cue is something you notice before your usual response. You choose the cue. You do not have to create pressure to find one.

Start with an action connected to your own statement when you have one. The accuracy example on this page is the demonstration when you do not.

**Good to know:** showing up, asking for help, using support, honoring a boundary, stopping at a stop rule, partly completing something, revising a plan, returning after a pause, repairing something, and choosing not to continue all count as evidence. Support and collaboration do not make the evidence less valid.', 'Use one small action as evidence', '["What small action would give you evidence about the statement from the last lesson? Use the accuracy example on this page only if you have no other action in mind.","Ownership check: If you are using a value, does it belong to you, or to the program, a facilitator, family, an employer, or a peer group? It’s fine to pick a different one, or to skip the value and keep the action.","What cue would help you notice a chance to practice? What do you usually do then?","What is the smallest action you could observe yourself taking?","Make a small practice plan: the action, a chance to try it in the next seven days, your limits, and when you’ll stop. Seven days is a window to notice chances, not a quota. If no chance comes up, record that. Planning only is valid."]'::jsonb, 'activity', 'One observable practice plan with a cue, limits, and a no-opportunity option.', '6ad18c2d5550b97a5e042b1b', '2026-10-16T02:30:05.275000'::timestamptz, '2026-10-20T03:20:44.537000'::timestamptz) on conflict (id) do update set "alias" = excluded."alias", "approval_note" = excluded."approval_note", "approval_state" = excluded."approval_state", "approved_source" = excluded."approved_source", "approved_version" = excluded."approved_version", "boundary" = excluded."boundary", "carry_forward" = excluded."carry_forward", "code" = excluded."code", "decision_options" = excluded."decision_options", "description" = excluded."description", "duration_min" = excluded."duration_min", "has_decision" = excluded."has_decision", "module_order" = excluded."module_order", "order" = excluded."order", "purpose" = excluded."purpose", "readings_note" = excluded."readings_note", "reflect_prompts" = excluded."reflect_prompts", "routes" = excluded."routes", "show" = excluded."show", "status" = excluded."status", "teach" = excluded."teach", "title" = excluded."title", "try_prompts" = excluded."try_prompts", "type" = excluded."type", "what_comes_out" = excluded."what_comes_out", "created_date" = excluded."created_date", "updated_date" = excluded."updated_date";
insert into public.admin_fields (entity, record_id, field, value) values ('Lesson', '6ad18c2d5550b97a5e042b1b', 'internal_notes', '19 Oct 2026. The purpose now ties the small action to the statement separated from a verdict in M4-L1. The value, standard, and practice plan stay. This is not a general values curriculum. The Next Decision menu is withheld here and offered at M4-L3.') on conflict (entity, record_id, field) do update set value = excluded.value;
insert into public.lesson ("alias", "approval_note", "approval_state", "approved_source", "approved_version", "boundary", "carry_forward", "code", "decision_options", "description", "duration_min", "has_decision", "module_order", "order", "purpose", "readings_note", "reflect_prompts", "routes", "show", "status", "teach", "title", "try_prompts", "type", "what_comes_out", "id", "created_date", "updated_date") values ('4.4 + 4.5', null, 'pending_approval', 'https://app.notion.com/p/3f1ca793c2c5813a9d9deabc94386c96', 'Build Otherwise approval — 2026-10-09; expanded app reading revision — 2026-10-09', 'Park, stop, redirect and keep looking are full outcomes. Moving on to the next module is not required. Don''t steer toward or away from any direction.', '["M6-L3","M3-L3"]'::jsonb, 'M6-L4', '[]'::jsonb, 'Everyone does a shared fit review (interest, conditions, demands, access, cost to the rest of life), with an optional place map and an optional access-vs-enjoyment check. Problem Fit × Builder Fit applies only on the problem/opportunity branch. Then choose one of the seven Next Decisions.', 30, true, 6, 4, 'Check how what you found fits your real life, then choose a next discovery decision.', null, '["Am I choosing this because of the evidence, or because one option sounds more impressive?"]'::jsonb, '["Shared fit review","Shared fit review + Problem Fit × Builder Fit (opportunity branch only)","Observe","Pass"]'::jsonb, '**Culinary example:** interest still high; early mornings conflict with a current shift (operating conditions); class fee unclear (access). A reasonable decision is **Test again**: find the fee and one schedule option before deciding anything bigger.', 'draft', 'Fit is not a score. It is a comparison between what you learned and what you are willing and able to do next.

You can check:

- Does this direction still interest you after you looked?
- What access do you actually have (time, money, people, location)?
- What would a small next step cost?
- What is still unknown?

The Next Decision words remain the same: Keep, Change, Test again, Pause, Stop, Another direction, Keep looking. “I don’t know yet” is a full answer. Record the decision, the reason, the next action, and when you will review it. You choose what stays private.', 'Check fit and choose your next discovery decision', '["Complete the shared fit review for your branch. Add the optional prompts only if they help."]'::jsonb, 'next_decision', 'An evidence note, your branch, and your Next Decision. An MVO (a short “minimum viable offer” sketch: the smallest thing you might try offering, if you want to) is optional, only for the problem/opportunity branch, and only if you want an offer-type try in Module 7. It is not required to finish.', '6ad18c2d5550b97a5e042b23', '2026-10-16T02:30:05.275000'::timestamptz, '2026-10-16T02:30:05.275000'::timestamptz) on conflict (id) do update set "alias" = excluded."alias", "approval_note" = excluded."approval_note", "approval_state" = excluded."approval_state", "approved_source" = excluded."approved_source", "approved_version" = excluded."approved_version", "boundary" = excluded."boundary", "carry_forward" = excluded."carry_forward", "code" = excluded."code", "decision_options" = excluded."decision_options", "description" = excluded."description", "duration_min" = excluded."duration_min", "has_decision" = excluded."has_decision", "module_order" = excluded."module_order", "order" = excluded."order", "purpose" = excluded."purpose", "readings_note" = excluded."readings_note", "reflect_prompts" = excluded."reflect_prompts", "routes" = excluded."routes", "show" = excluded."show", "status" = excluded."status", "teach" = excluded."teach", "title" = excluded."title", "try_prompts" = excluded."try_prompts", "type" = excluded."type", "what_comes_out" = excluded."what_comes_out", "created_date" = excluded."created_date", "updated_date" = excluded."updated_date";
insert into public.admin_fields (entity, record_id, field, value) values ('Lesson', '6ad18c2d5550b97a5e042b23', 'internal_notes', 'Source: Notion Module 4 L4 and L5, merged per the crosswalk (the database version had the decision inside L4). Discovery-decision words differ from the shared seven; reconcile before rehearsal.') on conflict (entity, record_id, field) do update set value = excluded.value;
insert into public.lesson ("alias", "approval_note", "approval_state", "approved_source", "approved_version", "boundary", "carry_forward", "code", "decision_options", "description", "duration_min", "has_decision", "module_order", "order", "purpose", "readings_note", "reflect_prompts", "routes", "show", "status", "teach", "title", "try_prompts", "type", "what_comes_out", "id", "created_date", "updated_date") values ('6.3', null, 'pending_approval', 'https://app.notion.com/p/87e875745def4ed4849b79f61bc91b9b', 'Build Otherwise approval — 2026-10-09; expanded app reading revision — 2026-10-09', 'Not financial advice. No spend, borrow, or fundraising pressure. No investor-ready or ROI theater. Don’t steer toward or away from any direction.', '["M8-L1","M8-L2"]'::jsonb, 'M8-L3', '[]'::jsonb, 'Use what you mapped to choose a financially honest Next Decision on one of three equal paths.', 30, true, 8, 3, 'Use your cost map, labor picture, constraints, and affordability boundary to choose one financially honest path and one Next Decision.', null, '[]'::jsonb, '["Pathway","Project/offer","Pause/Keep looking","Pass"]'::jsonb, '**Example:** A useful unpaid try might not be repeatable if it conflicts with paid work. That does not erase what you learned. It may mean the next step should protect income, use a different format, or pause until conditions change.', 'draft', 'A financially honest path is one that matches what you can actually afford and what you are willing to do next. It does not require a business idea, a loan, or a projected income.

Possible paths include:

- Continue with what you already have
- Change one part of the cost
- Pause and look for more information
- Stop this direction
- Look in a different direction

Every path counts. Record the path, the main reason, the next action, and when you will check again. You choose what stays private.', 'Choose a financially honest path', '["Which path, and why for now?","What does this path need to protect?","What remains unknown?"]'::jsonb, 'next_decision', 'A Financial Reality Note: the try or step, what was spent, received, owned or borrowed, and the labor; your affordability boundary; constraints you chose to name; your path; and your Next Decision. Moving on to Module 9 is optional.', '6ad18c2d5550b97a5e042b29', '2026-10-16T02:30:05.275000'::timestamptz, '2026-10-16T02:30:05.275000'::timestamptz) on conflict (id) do update set "alias" = excluded."alias", "approval_note" = excluded."approval_note", "approval_state" = excluded."approval_state", "approved_source" = excluded."approved_source", "approved_version" = excluded."approved_version", "boundary" = excluded."boundary", "carry_forward" = excluded."carry_forward", "code" = excluded."code", "decision_options" = excluded."decision_options", "description" = excluded."description", "duration_min" = excluded."duration_min", "has_decision" = excluded."has_decision", "module_order" = excluded."module_order", "order" = excluded."order", "purpose" = excluded."purpose", "readings_note" = excluded."readings_note", "reflect_prompts" = excluded."reflect_prompts", "routes" = excluded."routes", "show" = excluded."show", "status" = excluded."status", "teach" = excluded."teach", "title" = excluded."title", "try_prompts" = excluded."try_prompts", "type" = excluded."type", "what_comes_out" = excluded."what_comes_out", "created_date" = excluded."created_date", "updated_date" = excluded."updated_date";
insert into public.admin_fields (entity, record_id, field, value) values ('Lesson', '6ad18c2d5550b97a5e042b29', 'internal_notes', 'Source: Notion Module 6 L3.

FACILITATOR: do not assume a financial/benefits referral is available until confirmed.') on conflict (entity, record_id, field) do update set value = excluded.value;
insert into public.lesson ("alias", "approval_note", "approval_state", "approved_source", "approved_version", "boundary", "carry_forward", "code", "decision_options", "description", "duration_min", "has_decision", "module_order", "order", "purpose", "readings_note", "reflect_prompts", "routes", "show", "status", "teach", "title", "try_prompts", "type", "what_comes_out", "id", "created_date", "updated_date") values ('14', null, 'pending_approval', 'Entrepalooza Pilot 1 — Module Breakdown (Oct 5, 2026) · adopted Pilot 1 scope', 'Pilot 1 adopted card · lessons database copy Oct 6, 2026', 'No touch, movement, breathing, closed eyes or spiritual language is required. Calmness is not a completion requirement, and no distress is created. This is educational navigation, not treatment or crisis care.', '["M4-L3","M2-L2"]'::jsonb, 'M5-L1', '[]'::jsonb, 'Notice how an activity is going, then separate signal, story, urge, usual action, and cost. Listening comes before any adjustment. The choice to protect what works or change one thing comes in the next lesson.', 20, false, 5, 1, 'Listen to how an activity is going, tell the five parts apart, and find one point where a choice or a pause could be available.', null, '["Which parts were observations, and which were explanations or unknowns?","Before which action could you make a choice or pause?","What support, limit, or stop rule would help keep that choice available? If you brought a protective limit from Module 4, does it still fit here, or would you change it?"]'::jsonb, '["Start with an activity from my own try","Start with an activity that is going well","Start with the pressure cue I brought from Module 4","Use an ordinary task such as reading this page","Use a supplied case","Observe","Pass"]'::jsonb, '#### Observe reading this page

Use the real task in front of you: reading this paragraph. You do not need to change your breathing, close your eyes, or create a feeling.

Signal: notice whether your reading pace or attention changes. If you do not notice a change, that is the observation.  
Story: notice any meaning you attach to that change, or leave it unknown.  
Urge: notice any pull to reread, skip, continue, or stop, if one is present.  
Action: notice what you actually do.  
Cost: notice time or effort used; do not invent an after-effect.

This is an observation of an available task, with no assumed emotional response or outcome.', 'draft', 'Tuning your instrument means listening to how an activity is going, then either leaving a working setup alone or making one small reversible adjustment. The instrument is the way you are engaging right now. It is not you, and it is not a type of person. Tuning is relative to the rest of your life. Calm is not the target.

**If you''re coming from Module 4:** you may have brought a pressure cue, the thing you notice before your usual response. You can start with that. You can also start with the activity from your Module 2 try, or with an activity that is already going well. If you are not sure, start fresh. You do not have to bring anything.

An activity can matter and still leave room for the rest of your life. It can also start to feel pressured and hard to set down. Research calls these harmonious passion and obsessive passion. They describe a relationship with an activity, not a kind of person. One intense stretch cannot tell you which is which.

The question here is whether participation is still chosen, and what it costs. You do not need to decide which pattern you are in.

Listening comes before any adjustment. When you want to look more closely, use the map below. It watches choice, pressure, and cost without making that judgment.

A signal is a change you notice in your body, attention, pace, or energy. A story is the meaning you attach. An urge is what you feel pulled to do or avoid. Your usual action is what you commonly do next. Cost is what that action takes.

The sequence is signal → story → urge → usual action → cost. It is a way to separate observations, not a rule that everyone experiences all five in order. Any part can be absent or unknown. The aim is to keep a choice available. Calmness is not a completion requirement.

Start with your own activity when you have one. Reading this page is a demonstration you can use when you want a task that is already in front of you, or when you would rather not use your own. You do not need to change your breathing, close your eyes, or create a feeling.', 'Listen before you tune', '["Optional: If you brought a pressure cue from Module 4, where does it fit: signal, urge, outside condition, or not sure? You can skip this.","Signal: what change, if any, did you notice in your body, attention, pace, or energy?","Story: what meaning, if any, did you attach to it?","Urge: what did you feel pulled to do or avoid, if anything?","Usual action: what do you commonly do next? If unknown, describe only this attempt.","Cost: what time, effort, energy, or effect on responsibilities did you actually notice?","What outside condition or practical barrier mattered?"]'::jsonb, 'activity', 'One optional five-part map, and one support, condition, or stop rule. Choosing to protect what works or change one thing comes in the next lesson.', '6ad18c2d5550b97a5e042b1d', '2026-10-16T02:30:05.275000'::timestamptz, '2026-10-20T03:21:48.013000'::timestamptz) on conflict (id) do update set "alias" = excluded."alias", "approval_note" = excluded."approval_note", "approval_state" = excluded."approval_state", "approved_source" = excluded."approved_source", "approved_version" = excluded."approved_version", "boundary" = excluded."boundary", "carry_forward" = excluded."carry_forward", "code" = excluded."code", "decision_options" = excluded."decision_options", "description" = excluded."description", "duration_min" = excluded."duration_min", "has_decision" = excluded."has_decision", "module_order" = excluded."module_order", "order" = excluded."order", "purpose" = excluded."purpose", "readings_note" = excluded."readings_note", "reflect_prompts" = excluded."reflect_prompts", "routes" = excluded."routes", "show" = excluded."show", "status" = excluded."status", "teach" = excluded."teach", "title" = excluded."title", "try_prompts" = excluded."try_prompts", "type" = excluded."type", "what_comes_out" = excluded."what_comes_out", "created_date" = excluded."created_date", "updated_date" = excluded."updated_date";
insert into public.admin_fields (entity, record_id, field, value) values ('Lesson', '6ad18c2d5550b97a5e042b1d', 'internal_notes', '19 Oct 2026. This lesson now carries the Dualistic Model of Passion previously taught in M1-L2, because that model is about an activity that already matters. The five-part map remains the activity. The model is not a diagnosis and does not classify a participant. The Next Decision menu is withheld until M5-L3. 20 Oct 2026. Module frame is tuning your instrument: the instrument is the engagement, not the person. This lesson listens. The route choice belongs to M5-L2, and what_comes_out no longer claims it.') on conflict (entity, record_id, field) do update set value = excluded.value;
insert into public.lesson ("alias", "approval_note", "approval_state", "approved_source", "approved_version", "boundary", "carry_forward", "code", "decision_options", "description", "duration_min", "has_decision", "module_order", "order", "purpose", "readings_note", "reflect_prompts", "routes", "show", "status", "teach", "title", "try_prompts", "type", "what_comes_out", "id", "created_date", "updated_date") values ('5.2', null, 'pending_approval', 'https://app.notion.com/p/3f1ca793c2c58178a5d9e03d1604fd11', 'Build Otherwise approval — 2026-10-09; expanded app reading revision — 2026-10-09', 'No bigger second try is required.', '["M7-L1"]'::jsonb, 'M7-L2', '[]'::jsonb, 'Do the named try. Attempting it, attempting with support, planning only, or observing a demonstration all count the same when you record what happened.', 30, false, 7, 2, 'Do the try inside the limits you set, or observe or plan it instead.', null, '[]'::jsonb, '["Do the try","Do it with support","Observe","Plan only","Pause or stop"]'::jsonb, '**Example:** A planned beginner task may require a tool you cannot access. Recording “Tool unavailable; task not attempted” tells you what would need to change before you could find out more. It does not tell you whether you would enjoy the activity.', 'draft', 'Do the try you named. Stay inside the limits you set. If the stop rule appears, stop.

You do not have to finish the whole try for it to count. Stopping early, changing the plan, or deciding the try is not useful are all valid outcomes. Record what actually happened, not what you hoped would happen.

A bigger second try is not required in the same session.', 'Do the try', '["What actually happened?","If it didn''t happen, what got in the way, or is that still unknown?"]'::jsonb, 'experiment', 'A record of what happened, or a non-attempt.', '6ad18c2d5550b97a5e042b25', '2026-10-16T02:30:05.275000'::timestamptz, '2026-10-16T02:30:05.275000'::timestamptz) on conflict (id) do update set "alias" = excluded."alias", "approval_note" = excluded."approval_note", "approval_state" = excluded."approval_state", "approved_source" = excluded."approved_source", "approved_version" = excluded."approved_version", "boundary" = excluded."boundary", "carry_forward" = excluded."carry_forward", "code" = excluded."code", "decision_options" = excluded."decision_options", "description" = excluded."description", "duration_min" = excluded."duration_min", "has_decision" = excluded."has_decision", "module_order" = excluded."module_order", "order" = excluded."order", "purpose" = excluded."purpose", "readings_note" = excluded."readings_note", "reflect_prompts" = excluded."reflect_prompts", "routes" = excluded."routes", "show" = excluded."show", "status" = excluded."status", "teach" = excluded."teach", "title" = excluded."title", "try_prompts" = excluded."try_prompts", "type" = excluded."type", "what_comes_out" = excluded."what_comes_out", "created_date" = excluded."created_date", "updated_date" = excluded."updated_date";
insert into public.admin_fields (entity, record_id, field, value) values ('Lesson', '6ad18c2d5550b97a5e042b25', 'internal_notes', 'Source: Notion Module 5 module page + proposal summary of 5.2. Full lesson text not in upload.') on conflict (entity, record_id, field) do update set value = excluded.value;
insert into public.lesson ("alias", "approval_note", "approval_state", "approved_source", "approved_version", "boundary", "carry_forward", "code", "decision_options", "description", "duration_min", "has_decision", "module_order", "order", "purpose", "readings_note", "reflect_prompts", "routes", "show", "status", "teach", "title", "try_prompts", "type", "what_comes_out", "id", "created_date", "updated_date") values ('8.3', null, 'pending_approval', 'https://app.notion.com/p/126133fe89054eb5a34eecd503397881', 'Build Otherwise approval — 2026-10-09; expanded app reading revision — 2026-10-09', 'Completion does not require a public story, mentoring, unpaid labor, venture continuation, or permanent attendance. Participants may pass, leave, unfollow, or revise consent without exile.', '["M9-L3","M10-L1","M10-L2"]'::jsonb, 'M10-L3', '[]'::jsonb, 'Choose how close you want to stay, with every choice changeable later.', 30, true, 10, 3, 'Choose how close you want to stay, make each consent choice separately, and carry forward one next action.', null, '[]'::jsonb, '["Stay close","Light touch","Private / pause","Pass"]'::jsonb, '**Example:** Someone can take a job and choose light-touch contact. Another person can continue a project and choose privacy. Neither choice says how much the program mattered to them.', 'draft', 'Your place in the tribe is the choice you make about how (or whether) you stay connected after the pilot. Options include:

- Stay in regular contact
- Check in occasionally
- Pause and return later
- Leave
- Keep looking for a different form of connection

Every option is equal. Record the choice, the reason, and the next action if there is one. You can change it later. Nothing here requires a business, a recovery story, or a permanent identity.', 'Choose your place in the tribe', '["My connection choice:","Optional role (none / not now / role + time limit):","Follow-up: Yes / No / Not now","Media: Yes / No / Not now","Evaluation: Yes / No / Not now","Events: Yes / No / Not now","My privacy boundary:"]'::jsonb, 'next_decision', 'A Tribe Continuity Card: your shared group identity, your current path with belonging affirmed, your connection choice, any role interest and its time limit, one next action and review date, your separate consent choices, and your privacy boundary.', '6ad18c2d5550b97a5e042b2f', '2026-10-16T02:30:05.275000'::timestamptz, '2026-10-16T02:30:05.275000'::timestamptz) on conflict (id) do update set "alias" = excluded."alias", "approval_note" = excluded."approval_note", "approval_state" = excluded."approval_state", "approved_source" = excluded."approved_source", "approved_version" = excluded."approved_version", "boundary" = excluded."boundary", "carry_forward" = excluded."carry_forward", "code" = excluded."code", "decision_options" = excluded."decision_options", "description" = excluded."description", "duration_min" = excluded."duration_min", "has_decision" = excluded."has_decision", "module_order" = excluded."module_order", "order" = excluded."order", "purpose" = excluded."purpose", "readings_note" = excluded."readings_note", "reflect_prompts" = excluded."reflect_prompts", "routes" = excluded."routes", "show" = excluded."show", "status" = excluded."status", "teach" = excluded."teach", "title" = excluded."title", "try_prompts" = excluded."try_prompts", "type" = excluded."type", "what_comes_out" = excluded."what_comes_out", "created_date" = excluded."created_date", "updated_date" = excluded."updated_date";
insert into public.admin_fields (entity, record_id, field, value) values ('Lesson', '6ad18c2d5550b97a5e042b2f', 'internal_notes', 'Source: Notion Module 8 L3. Next action + review date carry from M9-L3 rather than being written again.') on conflict (entity, record_id, field) do update set value = excluded.value;
insert into public.lesson ("alias", "approval_note", "approval_state", "approved_source", "approved_version", "boundary", "carry_forward", "code", "decision_options", "description", "duration_min", "has_decision", "module_order", "order", "purpose", "readings_note", "reflect_prompts", "routes", "show", "status", "teach", "title", "try_prompts", "type", "what_comes_out", "id", "created_date", "updated_date") values ('13', null, 'pending_approval', 'Entrepalooza Pilot 1 — Module Breakdown (Oct 5, 2026) · adopted Pilot 1 scope', 'Pilot 1 adopted card · lessons database copy Oct 6, 2026', 'Keep the earlier wording visible so you can see what changed and why. Record practised, partly practised, missed with an opportunity, no opportunity, not attempted or unknown as descriptions, never scores. No diagnosis, treatment effect, or identity transformation is claimed.', '["M4-L1","M4-L2","M2-L3"]'::jsonb, 'M4-L3', '[]'::jsonb, 'Review practice evidence, keep earlier wording visible, revise the current statement, and choose the next behavior to carry into Module 5.', 20, true, 4, 3, 'Use new observations to revise a statement and choose a specific next action.', null, '["Which parts of the statement are supported, challenged, or still unknown? Did pressure, criticism, or shame shape the earlier story?","What responsibility, repair, support, or skill need remains?","What wording is more accurate now? You may keep it private. Starters if helpful: “The evidence shows that I…” / “Under these conditions, I was able to…” / “I don’t know yet, but I can test…”","What cue and protective limit, if any, will you carry into Module 5? (A protective limit is a boundary you choose to keep—like a time cap, a stop rule, or a responsibility you won’t drop.) Your next action and evidence stay with your Module 4 record."]'::jsonb, '["Answer privately","Use the page-description example","Observe","Pass","Pause or stop"]'::jsonb, '#### Check the wording against the page

The first lesson in Module 4 starts with four distinctions (event, story, verdict, uncertainty) and then offers optional deepeners.

The statement “the lesson teaches only four terms” can be checked by rereading it. The word “only” leaves out the optional deepeners.

A more accurate description is “the lesson starts with four main distinctions and then offers optional ways to check them.” This is a revision based on visible text, not a judgment about a reader.', 'draft', 'Revision means changing your wording when you learn something new. Keep your earlier wording available so you can see what changed and why.

Evidence is what you actually observed or can check. It may support part of your statement and challenge another part. One attempt rarely settles a broad claim. You can recognize responsibility and still describe context, uncertainty, or a skill you need. Carry one useful observation and a next action forward if you want to. You decide what stays private.', 'Review the evidence and revise your statement', '["What earlier statement do you want to review? Start with the statement you wrote in the last lessons if you have one. The page-description example is there when you do not.","What actually happened or what information can you check?"]'::jsonb, 'reflection', 'Earlier and revised wording, with selected evidence and one next action.', '6ad18c2d5550b97a5e042b1c', '2026-10-16T02:30:05.275000'::timestamptz, '2026-10-20T01:40:15.868000'::timestamptz) on conflict (id) do update set "alias" = excluded."alias", "approval_note" = excluded."approval_note", "approval_state" = excluded."approval_state", "approved_source" = excluded."approved_source", "approved_version" = excluded."approved_version", "boundary" = excluded."boundary", "carry_forward" = excluded."carry_forward", "code" = excluded."code", "decision_options" = excluded."decision_options", "description" = excluded."description", "duration_min" = excluded."duration_min", "has_decision" = excluded."has_decision", "module_order" = excluded."module_order", "order" = excluded."order", "purpose" = excluded."purpose", "readings_note" = excluded."readings_note", "reflect_prompts" = excluded."reflect_prompts", "routes" = excluded."routes", "show" = excluded."show", "status" = excluded."status", "teach" = excluded."teach", "title" = excluded."title", "try_prompts" = excluded."try_prompts", "type" = excluded."type", "what_comes_out" = excluded."what_comes_out", "created_date" = excluded."created_date", "updated_date" = excluded."updated_date";
insert into public.lesson ("alias", "approval_note", "approval_state", "approved_source", "approved_version", "boundary", "carry_forward", "code", "decision_options", "description", "duration_min", "has_decision", "module_order", "order", "purpose", "readings_note", "reflect_prompts", "routes", "show", "status", "teach", "title", "try_prompts", "type", "what_comes_out", "id", "created_date", "updated_date") values ('10', null, 'pending_approval', 'Entrepalooza Pilot 1 — Module Breakdown (Oct 5, 2026) · adopted Pilot 1 scope', 'Pilot 1 adopted card · lessons database copy Oct 6, 2026', 'Finishing a task alone does not show that its conditions are sustainable. Record practised, partly practised, no opportunity, not attempted and unknown as descriptions, never as scores. Ask permission before offering an interpretation, and accept correction or rejection.', '["M2-L2","M2-L3","M3-L2"]'::jsonb, 'M3-L3', '[]'::jsonb, 'Review the test and after-effect, correct facilitator interpretations, and carry only selected evidence into Module 4 (Check the Story).', 20, true, 3, 3, 'Separate the result, the cost and the explanation, then choose what is worth carrying forward.', null, '["What did it cost during and afterward? What is unknown?","Would you choose that condition again? What could change your mind?","Which observation and unanswered question, if any, do you want to carry into Module 4?"]'::jsonb, '["Answer privately","Observe","Carry only what you choose","Pass","Pause or stop"]'::jsonb, '#### Review a task without inventing a result

The reply example asks for the same three parts in a paragraph and in a checklist: say you got the message, name one thing you can do, and name when. There is no single correct wording.

Seeing that both formats ask for the same parts tells you nothing about effort, distraction, enjoyment, or later fatigue. Those require your own observations. Leave them unknown when you have no evidence.', 'draft', 'Review the task you actually tried. If the only thing you examined was the reply example, say so. Leave effort, distraction, enjoyment, and later fatigue unknown unless you have your own observations.

A useful review includes what happened and what it took. Cost can mean time, effort, fatigue, discomfort, or help needed afterward. Finishing a task alone does not show that its conditions are sustainable.

Compare your observation with your explanation. Keep uncertainty visible. You choose what to carry forward. A brief observation and an unanswered question are enough. You do not need a complete personal profile.', 'Review what helped and what it cost', '["What task and condition, if any, did you actually try?","What changed, and what else was different?","Did the condition affect choice, flexibility, enjoyment, pressure, or your ability to stop?"]'::jsonb, 'reflection', 'Selected evidence (only what you choose to keep), cost, uncertainty, and one note about what would make you change your mind.', '6ad18c2d5550b97a5e042b19', '2026-10-16T02:30:05.275000'::timestamptz, '2026-10-20T01:39:50.255000'::timestamptz) on conflict (id) do update set "alias" = excluded."alias", "approval_note" = excluded."approval_note", "approval_state" = excluded."approval_state", "approved_source" = excluded."approved_source", "approved_version" = excluded."approved_version", "boundary" = excluded."boundary", "carry_forward" = excluded."carry_forward", "code" = excluded."code", "decision_options" = excluded."decision_options", "description" = excluded."description", "duration_min" = excluded."duration_min", "has_decision" = excluded."has_decision", "module_order" = excluded."module_order", "order" = excluded."order", "purpose" = excluded."purpose", "readings_note" = excluded."readings_note", "reflect_prompts" = excluded."reflect_prompts", "routes" = excluded."routes", "show" = excluded."show", "status" = excluded."status", "teach" = excluded."teach", "title" = excluded."title", "try_prompts" = excluded."try_prompts", "type" = excluded."type", "what_comes_out" = excluded."what_comes_out", "created_date" = excluded."created_date", "updated_date" = excluded."updated_date";
insert into public.admin_fields (entity, record_id, field, value) values ('Lesson', '6ad18c2d5550b97a5e042b19', 'internal_notes', '19 Oct 2026. The review example no longer has a correct alphabetical order. The Next Decision menu stays on this lesson.') on conflict (entity, record_id, field) do update set value = excluded.value;
insert into public.lesson ("alias", "approval_note", "approval_state", "approved_source", "approved_version", "boundary", "carry_forward", "code", "decision_options", "description", "duration_min", "has_decision", "module_order", "order", "purpose", "readings_note", "reflect_prompts", "routes", "show", "status", "teach", "title", "try_prompts", "type", "what_comes_out", "id", "created_date", "updated_date") values ('11', null, 'pending_approval', 'Entrepalooza Pilot 1 — Module Breakdown (Oct 5, 2026) · adopted Pilot 1 scope', 'Pilot 1 adopted card · lessons database copy Oct 6, 2026', 'The goal is a more accurate statement you can revise, not a positive one. Feedback about an action is not a verdict about you, no cause is inferred, and no confession, public apology or identity claim is required.', '["M2-L2","M3-L3"]'::jsonb, 'M4-L1', '[]'::jsonb, 'Examine a selected event or fictional case and separate what happened from the meaning or identity verdict attached to it.', 20, false, 4, 1, 'Keep what happened separate from what you make it mean.', null, '["What more accurate statement fits the evidence now? It can remain uncertain.","Optional deepeners: What impact is known or assumed? What responsibility and context matter? What information challenges the first explanation?"]'::jsonb, '["Use what I brought from an earlier module","Use an everyday task","Use the fictional example","Reflect privately","Observe","Pass"]'::jsonb, '#### A fictional example — not a participant story

- **Event:** “The person stopped the activity after 20 minutes.”
- **Story:** “They can’t handle difficult things.”
- **Verdict:** “They never follow through.”
- **Revised, more accurate statement:** “They stopped after 20 minutes when the environment became difficult. The reason isn’t established yet.”

Notice the link to the stop rules in Modules 2 and 3: stopping can be a planned, sensible choice, not a failure.', 'draft', 'If you brought a record from Module 2 or Module 3, start there. The fictional example shows the distinctions when you would rather not use your own event.

This is the same move you practiced earlier: keep what happened separate from what you make it mean.

An event is what happened, described so someone else could observe or check it. A story is the meaning or explanation you attach. A verdict turns one event into a judgment about who you are. Uncertainty is what you don’t know yet. It is allowed to stay unknown.

A harsh verdict can start a loop that reduces future tries. Separating the event from the verdict gives you another path: an accurate description, a question to check, and another small try if you want one. Feedback about an action is not a verdict about you. The goal is a more accurate statement you can revise. It does not have to sound positive.', 'Separate what happened from what it means', '["What happened that you could observe or check? Start with something you brought from Module 2 or 3 if you have it. The fictional example is there when you do not.","What story, if any, was added?","What verdict, if any, followed? “None” or “I don’t know” is valid.","What is still uncertain?"]'::jsonb, 'reading', 'An event/story/verdict/uncertainty distinction and a more accurate, revisable statement.', '6ad18c2d5550b97a5e042b1a', '2026-10-16T02:30:05.275000'::timestamptz, '2026-10-20T01:40:15.263000'::timestamptz) on conflict (id) do update set "alias" = excluded."alias", "approval_note" = excluded."approval_note", "approval_state" = excluded."approval_state", "approved_source" = excluded."approved_source", "approved_version" = excluded."approved_version", "boundary" = excluded."boundary", "carry_forward" = excluded."carry_forward", "code" = excluded."code", "decision_options" = excluded."decision_options", "description" = excluded."description", "duration_min" = excluded."duration_min", "has_decision" = excluded."has_decision", "module_order" = excluded."module_order", "order" = excluded."order", "purpose" = excluded."purpose", "readings_note" = excluded."readings_note", "reflect_prompts" = excluded."reflect_prompts", "routes" = excluded."routes", "show" = excluded."show", "status" = excluded."status", "teach" = excluded."teach", "title" = excluded."title", "try_prompts" = excluded."try_prompts", "type" = excluded."type", "what_comes_out" = excluded."what_comes_out", "created_date" = excluded."created_date", "updated_date" = excluded."updated_date";
insert into public.admin_fields (entity, record_id, field, value) values ('Lesson', '6ad18c2d5550b97a5e042b1a', 'internal_notes', '19 Oct 2026. The Next Decision menu is withheld on this reading. It is offered at M4-L3, after there is a statement to revisit.') on conflict (entity, record_id, field) do update set value = excluded.value;
insert into public.lesson ("alias", "approval_note", "approval_state", "approved_source", "approved_version", "boundary", "carry_forward", "code", "decision_options", "description", "duration_min", "has_decision", "module_order", "order", "purpose", "readings_note", "reflect_prompts", "routes", "show", "status", "teach", "title", "try_prompts", "type", "what_comes_out", "id", "created_date", "updated_date") values ('8.1', null, 'pending_approval', 'https://app.notion.com/p/41a7c569b57143dc985bc485970ac1ad', 'Build Otherwise approval — 2026-10-09; expanded app reading revision — 2026-10-09', 'No trauma story, public testimony, or redemption arc. No promise of a guaranteed family, recovery community, job, or revenue. Belonging is not therapy or treatment. No hardship-as-admission-ticket and no cliques-as-curriculum.', '["M9-L3"]'::jsonb, 'M10-L1', '[]'::jsonb, 'Name the shared identity of this group in plain words, with every exit path belonging.', 30, false, 10, 1, 'Name who this group is together while protecting disagreement, privacy, and every exit path.', null, '[]'::jsonb, '["Share one line","Answer privately","Observe","Pass"]'::jsonb, '**Example:** Two people might learn from the same session and make different decisions: one continues a project, while the other parks it to protect a work schedule. They can still exchange useful observations without treating either decision as a failure.', 'draft', 'This module is about what continues after the pilot, not about who belongs in a permanent group.

“Who we are together” means naming the people, practices, or supports that already exist or that you want to keep. It is not a membership test. You can name one person, one practice, or none.

No one is required to stay connected. Leaving, pausing, or choosing not to join anything else are full finishes.', 'Who we are together', '["Our shared identity, in one line:","My path right now, named without shame:","Optional: what I''m carrying forward (can stay private):"]'::jsonb, 'reflection', 'One shared group-identity line, and your current path named without shame.', '6ad18c2d5550b97a5e042b2d', '2026-10-16T02:30:05.275000'::timestamptz, '2026-10-16T02:30:05.275000'::timestamptz) on conflict (id) do update set "alias" = excluded."alias", "approval_note" = excluded."approval_note", "approval_state" = excluded."approval_state", "approved_source" = excluded."approved_source", "approved_version" = excluded."approved_version", "boundary" = excluded."boundary", "carry_forward" = excluded."carry_forward", "code" = excluded."code", "decision_options" = excluded."decision_options", "description" = excluded."description", "duration_min" = excluded."duration_min", "has_decision" = excluded."has_decision", "module_order" = excluded."module_order", "order" = excluded."order", "purpose" = excluded."purpose", "readings_note" = excluded."readings_note", "reflect_prompts" = excluded."reflect_prompts", "routes" = excluded."routes", "show" = excluded."show", "status" = excluded."status", "teach" = excluded."teach", "title" = excluded."title", "try_prompts" = excluded."try_prompts", "type" = excluded."type", "what_comes_out" = excluded."what_comes_out", "created_date" = excluded."created_date", "updated_date" = excluded."updated_date";
insert into public.admin_fields (entity, record_id, field, value) values ('Lesson', '6ad18c2d5550b97a5e042b2d', 'internal_notes', 'Source: Notion Module 8 L1. Facilitator line: ''You''re still of this tribe if you want to be.'' Belonging research (Walton et al. 2023, Haslam/Jetten) is design analogy only.

FACILITATOR: Offer the starting identity line for revision. Affirm that employment, training, project or venture, pause, keep looking, and leaving are full-member paths, not dropout categories. Optional closing line: “You’re still of this tribe if you want to be.”') on conflict (entity, record_id, field) do update set value = excluded.value;
insert into public.lesson ("alias", "approval_note", "approval_state", "approved_source", "approved_version", "boundary", "carry_forward", "code", "decision_options", "description", "duration_min", "has_decision", "module_order", "order", "purpose", "readings_note", "reflect_prompts", "routes", "show", "status", "teach", "title", "try_prompts", "type", "what_comes_out", "id", "created_date", "updated_date") values ('0.5', null, 'pending_approval', 'Breakdown — Pilot 1 (3f1ca793c2c5818ea667d1383885ea7a) · Lessons — Modules 0, 4–8 (3f1ca793c2c581108a93fc2df2c9f49e)', 'Build Otherwise copy of Lessons database, Oct 6, 2026 (copy of live Ashley Zeck workspace source; not rehearsed)', 'Don’t invent testimonials or require a recovery or business narrative.', '[]'::jsonb, 'O.1', '[]'::jsonb, 'Welcome. 

Say plainly what this pilot is (a structured way to notice, try, reflect, and decide, with every exit path counted) and what it isn''t (therapy, treatment, a job or income promise, a readiness test, or a required business).', 5, false, 0, 1, 'Know what this is, what it isn’t, and what stays yours, before you decide anything.', null, '[""]'::jsonb, '["Say it","Write it","Watch","Pass"]'::jsonb, null, 'draft', '## Welcome

Entrepalooza helps you explore interests and possibilities through learning, conversation, and small real-world experiences. You don’t need to know your direction before you begin.

Entrepreneurship is one possible direction. It isn’t a required destination.

## What this is, and isn’t

This is a structured way to notice, try something small, reflect on what happened, and decide what’s next. A job, training, a project, a business, a pause, or still looking all are valid outcomes.

It is not therapy or treatment. It is not a promise of a job, income, or business success. It is not a test of whether you’re ready. You don’t have to tell your story.

## What stays yours

You decide what to share. What you write stays in your account. Other participants can’t see it, and your private journal isn’t shared unless you choose to share it. Build Otherwise administrators run this app and may access the information stored in it. You can skip any question without giving a reason. In Settings, you can download or delete your workbook, journal, Life Map, and related reflections. My Records is managed separately. You are not required to share medical, legal, or other sensitive personal history. If we ever ask to use your words, record something, or follow up later, each one gets its own yes or no.

You can change direction, pause, or stop at any time. To pause or leave, email Start@buildotherwise.org. No reason needed.

Type in any box, or tap Dictate and talk like you’re telling a friend. Questions or concerns: Start@buildotherwise.org.', 'Welcome: what this is, and what stays private', '["","",""]'::jsonb, 'orientation', null, '6ad18c2d5550b97a5e042b0c', '2026-10-16T02:30:05.273000'::timestamptz, '2026-10-30T07:08:28.578000'::timestamptz) on conflict (id) do update set "alias" = excluded."alias", "approval_note" = excluded."approval_note", "approval_state" = excluded."approval_state", "approved_source" = excluded."approved_source", "approved_version" = excluded."approved_version", "boundary" = excluded."boundary", "carry_forward" = excluded."carry_forward", "code" = excluded."code", "decision_options" = excluded."decision_options", "description" = excluded."description", "duration_min" = excluded."duration_min", "has_decision" = excluded."has_decision", "module_order" = excluded."module_order", "order" = excluded."order", "purpose" = excluded."purpose", "readings_note" = excluded."readings_note", "reflect_prompts" = excluded."reflect_prompts", "routes" = excluded."routes", "show" = excluded."show", "status" = excluded."status", "teach" = excluded."teach", "title" = excluded."title", "try_prompts" = excluded."try_prompts", "type" = excluded."type", "what_comes_out" = excluded."what_comes_out", "created_date" = excluded."created_date", "updated_date" = excluded."updated_date";
