insert into public.lesson ("alias", "approval_note", "approval_state", "approved_source", "approved_version", "boundary", "carry_forward", "code", "decision_options", "description", "duration_min", "has_decision", "module_order", "order", "purpose", "readings_note", "reflect_prompts", "routes", "show", "status", "teach", "title", "try_prompts", "type", "what_comes_out", "id", "created_date", "updated_date") values ('2', null, 'pending_approval', 'Breakdown — Pilot 1 (3f1ca793c2c5818ea667d1383885ea7a) · Lessons — Modules 0, 4–8 (3f1ca793c2c581108a93fc2df2c9f49e)', 'Build Otherwise copy of Lessons database, Oct 6, 2026 (copy of live Ashley Zeck workspace source; not rehearsed)', 'Keep participant choice, the right to pass, and facilitator boundaries intact.', '[]'::jsonb, 'O.3', '[]'::jsonb, 'Use the fictional supply-shelf scenario. A peer asks whether the participant wants a question, suggestion, or no feedback. The participant may accept, reject, or revise the idea. Debrief who made the decision and what pressure would have looked like. Observation and passing are valid.', 12, false, 0, 3, 'Practice giving, receiving, declining, and revising feedback without pressure.', null, '["Who made the decision in the example? What would pressure have looked like?"]'::jsonb, '["Say it","Write it","Watch","Pass"]'::jsonb, '**Fictional example:** Someone has sketched a plan for organizing a shared supply shelf. A peer thinks a different layout would work better.

1. Peer asks: “Would you like a question, a suggestion, or no feedback right now?”
2. The person chooses, including “no.” If no, the peer says “Okay” and drops it.
3. If a question is welcome: “What would you want someone to find first?” If a suggestion is welcome: “Would putting the most-used items nearest the front help?”
4. The person can take the idea, leave it, or change it.

On your own: read both roles and notice where permission was asked.', 'draft', 'The Group Code is a group agreement, not a loyalty pledge. You don’t have to call yourself a builder to use it.

The core practice is asking before you give advice, challenge an interpretation, or share someone’s work. Respect “no,” “not now,” passing, and changing one’s mind. Speak about an action or a piece of evidence; do not diagnose or assign an identity. Offer only support you can actually provide.

Agreeing to the Code means you’ve read it. It does not take away your right to pass or your privacy.', 'How we give feedback', '["Using the supply-shelf example, pick the reply you''d want: “A question is okay,” “I’d like a suggestion,” or “No feedback right now.”","Optional: one line of the Group Code you''d want explained more."]'::jsonb, 'orientation', 'A short record or observation. Private and pass routes count.', '6ad18c2d5550b97a5e042b0e', '2026-10-16T02:30:05.273000'::timestamptz, '2026-10-16T02:30:05.273000'::timestamptz) on conflict (id) do update set "alias" = excluded."alias", "approval_note" = excluded."approval_note", "approval_state" = excluded."approval_state", "approved_source" = excluded."approved_source", "approved_version" = excluded."approved_version", "boundary" = excluded."boundary", "carry_forward" = excluded."carry_forward", "code" = excluded."code", "decision_options" = excluded."decision_options", "description" = excluded."description", "duration_min" = excluded."duration_min", "has_decision" = excluded."has_decision", "module_order" = excluded."module_order", "order" = excluded."order", "purpose" = excluded."purpose", "readings_note" = excluded."readings_note", "reflect_prompts" = excluded."reflect_prompts", "routes" = excluded."routes", "show" = excluded."show", "status" = excluded."status", "teach" = excluded."teach", "title" = excluded."title", "try_prompts" = excluded."try_prompts", "type" = excluded."type", "what_comes_out" = excluded."what_comes_out", "created_date" = excluded."created_date", "updated_date" = excluded."updated_date";
insert into public.admin_fields (entity, record_id, field, value) values ('Lesson', '6ad18c2d5550b97a5e042b0e', 'internal_notes', 'Source: https://app.notion.com/p/3f1ca793c2c5817e8549e9cbb65b521a — rebuilt Oct 12 2026 from Build Otherwise copy (Oct 6)

