insert into public.admin_fields (entity, record_id, field, value) values ('LibraryResource', '6acfc09e150c2cf1c514aa6e', 'internal_notes', 'Added by Claude, Oct 12 2026 — draft, awaiting Ashley''s approval. Ashley''s own named source. Flag: recovery-adjacent framing; the program is not a recovery program — decide if participant-facing fits. Rat Park evidence it cites is contested.') on conflict (entity, record_id, field) do update set value = excluded.value;
insert into public.library_resource ("audience", "body", "creator", "duration_min", "kind", "lesson_code", "module_order", "order", "publisher", "review_status", "source_label", "status", "summary", "title", "topics", "url", "why_here", "year", "id", "created_date", "updated_date") values ('participant', null, 'Josh Lerner and Ulrike Malmendier', null, 'study', null, 4, 1010, 'The Review of Financial Studies (NBER working paper 16918, 2011)', 'published', 'Outside source. Found by Claude, Oct 12, 2026. NBER working-paper record (published version in Review of Financial Studies).', 'published', 'Follows business-school classmates. Students with more classmates who had business experience were less likely to start a business afterward. The drop came from fewer ventures that failed, not from fewer that succeeded. The classmates were Harvard Business School students, so it is not evidence that Entrepalooza works.', 'With a little help from my (random) friends: success and failure in post-business school entrepreneurship', '[]'::jsonb, 'https://ideas.repec.org/p/nbr/nberwo/16918.html', 'Follows business-school classmates. Students with more classmates who had business experience were less likely to start a business afterward. The drop came from fewer ventures that failed, not from fewer that succeeded. The classmates were Harvard Business School students, so it is not evidence that Entrepalooza works.', 2013, '6acfc09e150c2cf1c514aa77', '2026-10-14T17:49:18.235000'::timestamptz, '2026-10-19T19:47:45.903000'::timestamptz) on conflict (id) do update set "audience" = excluded."audience", "body" = excluded."body", "creator" = excluded."creator", "duration_min" = excluded."duration_min", "kind" = excluded."kind", "lesson_code" = excluded."lesson_code", "module_order" = excluded."module_order", "order" = excluded."order", "publisher" = excluded."publisher", "review_status" = excluded."review_status", "source_label" = excluded."source_label", "status" = excluded."status", "summary" = excluded."summary", "title" = excluded."title", "topics" = excluded."topics", "url" = excluded."url", "why_here" = excluded."why_here", "year" = excluded."year", "created_date" = excluded."created_date", "updated_date" = excluded."updated_date";
insert into public.admin_fields (entity, record_id, field, value) values ('LibraryResource', '6acfc09e150c2cf1c514aa77', 'internal_notes', 'Added by Claude, Oct 12 2026 — draft, awaiting Ashley''s approval. Cited in M4 L2. Harvard MBA population.') on conflict (entity, record_id, field) do update set value = excluded.value;
insert into public.library_resource ("audience", "body", "creator", "duration_min", "kind", "lesson_code", "module_order", "order", "publisher", "review_status", "source_label", "status", "summary", "title", "topics", "url", "why_here", "year", "id", "created_date", "updated_date") values ('program_team', null, null, null, 'research_brief', null, null, 1, null, 'published', 'Notion · entrepalooza2020 · Evidence Library · attached file all-modules-research-oct5-2026.md (66,225 characters)', 'published', 'Research for every module, including studies that support the design and studies that cut against it. Each piece is marked as direct evidence or as evidence from a similar setting.', 'Research brief: all modules (Oct 5, 2026)', '[]'::jsonb, null, 'Research for every module, including studies that support the design and studies that cut against it. Each piece is marked as direct evidence or as evidence from a similar setting.', null, '6acfc09e150c2cf1c514aa5e', '2026-10-14T17:49:18.235000'::timestamptz, '2026-10-14T17:49:18.235000'::timestamptz) on conflict (id) do update set "audience" = excluded."audience", "body" = excluded."body", "creator" = excluded."creator", "duration_min" = excluded."duration_min", "kind" = excluded."kind", "lesson_code" = excluded."lesson_code", "module_order" = excluded."module_order", "order" = excluded."order", "publisher" = excluded."publisher", "review_status" = excluded."review_status", "source_label" = excluded."source_label", "status" = excluded."status", "summary" = excluded."summary", "title" = excluded."title", "topics" = excluded."topics", "url" = excluded."url", "why_here" = excluded."why_here", "year" = excluded."year", "created_date" = excluded."created_date", "updated_date" = excluded."updated_date";
insert into public.admin_fields (entity, record_id, field, value) values ('LibraryResource', '6acfc09e150c2cf1c514aa5e', 'internal_notes', 'Original review_status (Oct 13 cleanup): Faithful Notion copy of the box research file. Adjacent research supports design logic by analogy; it does not validate Entrepalooza outcomes. No new claims added in this transfer.') on conflict (entity, record_id, field) do update set value = excluded.value;
insert into public.library_resource ("audience", "body", "creator", "duration_min", "kind", "lesson_code", "module_order", "order", "publisher", "review_status", "source_label", "status", "summary", "title", "topics", "url", "why_here", "year", "id", "created_date", "updated_date") values ('participant', '## Interest can grow through experience

People are often told to find their passion, as though it already exists in finished form. Research on interest development suggests a different possibility: interest can be sparked by an encounter, then maintained or deepened through repeated engagement, new knowledge, and a growing sense of value. It can also fade. There is no guarantee that an initial spark turns into a lasting pursuit.

That distinction matters because you cannot recognize every possible interest in advance. Some things only become interesting once you have access to them, meet people involved in them, or learn enough to see what is possible.

## Curiosity is not a commitment

You might be drawn to a subject because you enjoy it, because it frustrates you, because it affects your life, or because someone introduced you to it. Repeated attention alone does not reveal which explanation fits. Nor does being skilled at something automatically mean you want to keep doing it.

Consider three different questions:

- **What have I encountered?** Opportunities and exposure shape what you can even consider.
- **What catches my attention, and why?** Curiosity, concern, obligation, and familiarity can look similar at first.
- **What would help me learn more?** A conversation, observation, reading, visit, or small real-world try can tell you more than guessing what your future should be.

Not everything important has to become a job, business, or lifelong identity. An interest can enrich your life without becoming a plan.

## Something worth investigating

You do not need to name your calling here. Choose a question you actually want answered—or look for an unfamiliar possibility to encounter. You are gathering information about what is available and what matters to you, not making a permanent choice.

**Research connection:** Hidi and Renninger''s four-phase model describes how interest may develop from triggered situational interest toward more enduring individual interest. It is a developmental model, not a promise about any one person''s future.', null, null, 'reading', 'M1-L1', 1, 100, null, 'published', 'Notion Module 1 (working replacement draft, copy of Oct 6, 2026), Reading 1, in the source''s own words.', 'published', null, 'How Interests Begin', '[]'::jsonb, null, null, null, '6acfc09e150c2cf1c514aa62', '2026-10-14T17:49:18.235000'::timestamptz, '2026-10-17T02:42:37.771000'::timestamptz) on conflict (id) do update set "audience" = excluded."audience", "body" = excluded."body", "creator" = excluded."creator", "duration_min" = excluded."duration_min", "kind" = excluded."kind", "lesson_code" = excluded."lesson_code", "module_order" = excluded."module_order", "order" = excluded."order", "publisher" = excluded."publisher", "review_status" = excluded."review_status", "source_label" = excluded."source_label", "status" = excluded."status", "summary" = excluded."summary", "title" = excluded."title", "topics" = excluded."topics", "url" = excluded."url", "why_here" = excluded."why_here", "year" = excluded."year", "created_date" = excluded."created_date", "updated_date" = excluded."updated_date";
