insert into public.library_resource ("audience", "body", "creator", "duration_min", "kind", "lesson_code", "module_order", "order", "publisher", "review_status", "source_label", "status", "summary", "title", "topics", "url", "why_here", "year", "id", "created_date", "updated_date") values ('participant', null, 'Michael M. Gielnik and colleagues', null, 'study', null, 2, 1009, 'Academy of Management Learning & Education', 'published', 'Outside source. Found by Claude, Oct 12, 2026. Effectuation.org publications library listing.', 'published', 'A randomized evaluation of a university training in Uganda where students learned by actually starting small ventures during the course. Compared with a control group, more of them went on to start businesses. The course aimed at starting businesses, so it is not evidence that Entrepalooza works.', 'Action and action-regulation in entrepreneurship: evaluating a student training for promoting entrepreneurship', '[]'::jsonb, 'https://effectuation.org/publications-library/action-and-action-regulation-in-entrepreneurship-evaluating-a-student-training-for-promoting-entrepreneurship', 'A randomized evaluation of a university training in Uganda where students learned by actually starting small ventures during the course. Compared with a control group, more of them went on to start businesses. The course aimed at starting businesses, so it is not evidence that Entrepalooza works.', 2015, '6acfc09e150c2cf1c514aa76', '2026-10-14T17:49:18.235000'::timestamptz, '2026-10-19T19:47:45.648000'::timestamptz) on conflict (id) do update set "audience" = excluded."audience", "body" = excluded."body", "creator" = excluded."creator", "duration_min" = excluded."duration_min", "kind" = excluded."kind", "lesson_code" = excluded."lesson_code", "module_order" = excluded."module_order", "order" = excluded."order", "publisher" = excluded."publisher", "review_status" = excluded."review_status", "source_label" = excluded."source_label", "status" = excluded."status", "summary" = excluded."summary", "title" = excluded."title", "topics" = excluded."topics", "url" = excluded."url", "why_here" = excluded."why_here", "year" = excluded."year", "created_date" = excluded."created_date", "updated_date" = excluded."updated_date";
insert into public.admin_fields (entity, record_id, field, value) values ('LibraryResource', '6acfc09e150c2cf1c514aa76', 'internal_notes', 'Added by Claude, Oct 12 2026 — draft, awaiting Ashley''s approval. Gielnik gave feedback on the curriculum.') on conflict (entity, record_id, field) do update set value = excluded.value;
insert into public.library_resource ("audience", "body", "creator", "duration_min", "kind", "lesson_code", "module_order", "order", "publisher", "review_status", "source_label", "status", "summary", "title", "topics", "url", "why_here", "year", "id", "created_date", "updated_date") values ('participant', '#### From Module 4 to here

In Module 4, you practiced separating what happened from the story you built around it.

You asked:

What does the evidence actually support?

Module 5 keeps that same discipline, but now we are looking at intensity while something is happening.

Maybe you become deeply absorbed.

Maybe your pace picks up.

Maybe you feel pressure.

Maybe you want to push harder.

Maybe you want to avoid the whole thing.

Maybe nothing feels especially intense at all.

The goal is not to decide that intensity is good or bad.

The question is:

What is the intensity doing, and what choices are still available to me?

One way to hold that question is tuning your instrument. The instrument is the way you are engaging an activity right now, not you as a person. This reading is the listening. You might later leave a working setup alone, or make one small reversible change. Calm is not the target, and one stretch cannot tell you what kind of person you are.

---

#### Useful does not mean calm

It is easy to assume that the “healthy” version of engagement should look calm, balanced, and peaceful all the time.

That is not the standard here.

You can be excited, energized, focused, frustrated, nervous, or deeply absorbed and still be making choices that work for you.

You can also look calm while something is going badly.

So Entrepalooza is not teaching emotional calmness as the goal.

We care more about things such as:

- Can I still choose?
- Can I adjust?
- Can I stop if I need to?
- Can I protect things outside this activity that matter?
- What is this costing me?
- Is the way I am doing this still workable?

Research on passion gives us one reason to pay attention to those questions.

Someone can spend many hours on an activity because it matters to them, because others depend on them, because it has become a habit, or because stepping away feels threatening. The number of hours does not tell you how the activity fits the rest of life.

The Dualistic Model of Passion, associated with Robert Vallerand and colleagues, describes two forms of engagement. In harmonious passion, a valued activity is more readily integrated with other important parts of life. In obsessive passion, involvement may become more controlled by internal pressure and harder to balance with competing needs.

Both describe a relationship with an activity. They are not diagnoses, fixed identities, or a claim that one difficult day reveals a stable pattern. Choice, expectations, money, access, rest, and responsibilities can all shape what participation looks like. Stopping or reducing an activity does not mean it lacked meaning.

The research describes tendencies across groups. A short reflection cannot establish which pattern someone is in, and the model is only one lens. It gives us something to watch: whether participation is still chosen, and what it costs.

Use an activity you have actually been in when you have one: the try from Module 2, something that is going well, or a cue you brought from Module 4. Reading this page can show you the five words. It is the example, not a substitute for your own activity.

#### A map for noticing

Entrepalooza uses five words:

**Signal**

A change you notice in your body, attention, pace, or energy.

**Story**

The meaning or explanation you attach to what is happening.

**Urge**

A pull to do something or avoid something.

**Action**

What you actually do.

**Cost**

What the action requires or affects, such as time, energy, effort, recovery, money, relationships, responsibilities, or something else you wanted to protect.

This is a teaching map.

It is not a scientific claim that every human experience unfolds in exactly five steps.

Parts may happen together.

Some may not appear at all.

You may not know what one of them was.

That is fine.

The map exists to help you slow the scene down enough to notice where choices may exist.

#### A signal does not tell you its cause

Suppose you notice your attention becoming extremely narrow.

That is a signal.

It does not automatically tell you:

“This is hyperfocus.”

“This is anxiety.”

“This is passion.”

“This is trauma.”

“This means I should stop.”

You observed a change in attention.

That is what you know.

The cause may be unclear.

The same applies to a racing heart, restless energy, shutting down, wanting to leave, working faster, or becoming completely absorbed.

Noticing comes before explaining.

#### Then notice the story

Maybe the signal is:

“I have been working much faster for the last hour.”

The story might be:

“I finally found what I’m meant to do.”

Or:

“I have to finish this tonight or I’ll lose momentum.”

Or there may be no clear story at all.

Again, the point is not to argue with every thought.

It is to notice when an interpretation has joined the event.

#### Then notice the urge and action

An urge might be:

“Keep going.”

“Check it again.”

“Quit.”

“Hide it.”

“Spend more money.”

“Tell everybody.”

“Do one more hour.”

“Walk away.”

An urge is not the same thing as an action.

You can notice an urge without automatically following it.

Then ask:

What did I actually do?

That is the action.

#### And what did it cost?

Cost does not mean punishment.

It means what the action required or affected.

Maybe you worked intensely for two hours and felt fine afterward.

Maybe you accomplished a lot but skipped something important.

Maybe continuing required very little.

Maybe you needed the rest of the day to recover.

Maybe there was no noticeable cost.

Do not invent one just because the worksheet asks.

When something is going well, the answer may simply be:

“This remained workable.”

That matters because Module 5 has two equal routes.

You do not have to manufacture a problem in order to complete it.

#### Carry this question forward

When intensity changes, what do I actually notice, and what choices are still available?', null, null, 'reading', 'M5-L1', 5, 109, null, 'published', 'Notion Module 3 (working replacement draft, copy of Oct 6, 2026), Reading 1, in the source''s own words. 19 Oct 2026: the Dualistic Model of Passion explanation was added from the former Module 1 reading.', 'published', null, 'Intensity Is Not Automatically the Problem', '[]'::jsonb, null, null, null, '6acfc09e150c2cf1c514aa6b', '2026-10-14T17:49:18.235000'::timestamptz, '2026-10-21T20:46:45.245000'::timestamptz) on conflict (id) do update set "audience" = excluded."audience", "body" = excluded."body", "creator" = excluded."creator", "duration_min" = excluded."duration_min", "kind" = excluded."kind", "lesson_code" = excluded."lesson_code", "module_order" = excluded."module_order", "order" = excluded."order", "publisher" = excluded."publisher", "review_status" = excluded."review_status", "source_label" = excluded."source_label", "status" = excluded."status", "summary" = excluded."summary", "title" = excluded."title", "topics" = excluded."topics", "url" = excluded."url", "why_here" = excluded."why_here", "year" = excluded."year", "created_date" = excluded."created_date", "updated_date" = excluded."updated_date";
insert into public.admin_fields (entity, record_id, field, value) values ('LibraryResource', '6acfc09e150c2cf1c514aa6b', 'internal_notes', 'ROLE: PRIMARY participant reading for this step. DMP rule (Oct 19, 2026): the Dualistic Model of Passion is explained ONLY in M5-L1 ''Intensity Is Not Automatically the Problem''; M1-L2 ''Attention is not a passion'' carries the caution and points forward to Module 5. Still pending founder approval until rehearsed.') on conflict (entity, record_id, field) do update set value = excluded.value;
insert into public.library_resource ("audience", "body", "creator", "duration_min", "kind", "lesson_code", "module_order", "order", "publisher", "review_status", "source_label", "status", "summary", "title", "topics", "url", "why_here", "year", "id", "created_date", "updated_date") values ('participant', 'Real interests can develop through new experiences, not just private reflection. Possible ways to encounter work or activities include observing a trade, attending a library workshop, talking to someone in a profession, visiting a community event, taking an introductory class, or helping with an accessible project.

A useful choice depends on what you want to learn and what is realistically available. Consider time, transportation, costs, accessibility, and responsibilities. A conversation or observation may be more feasible than a hands-on activity. No opportunity should require a purchase or a business commitment.

An actual local menu of opportunities will require partners and participant locations; this reading does not pretend such a menu already exists.', null, null, 'reading', 'M2-L1', 2, 201, null, 'draft', 'Curriculum step M2-L1 — Choose an interest or try something new, from the approved curriculum records.', 'draft', 'Choose an existing interest, a bounded exposure, or a no-clue-yet route, and design one small try you can actually learn from.', 'Where Could You Encounter Something New?', '[]'::jsonb, null, 'Choose an existing interest, a bounded exposure, or a no-clue-yet route, and design one small try you can actually learn from.', null, '6acfc09e150c2cf1c514aa53', '2026-10-14T17:49:18.235000'::timestamptz, '2026-10-21T20:46:42.920000'::timestamptz) on conflict (id) do update set "audience" = excluded."audience", "body" = excluded."body", "creator" = excluded."creator", "duration_min" = excluded."duration_min", "kind" = excluded."kind", "lesson_code" = excluded."lesson_code", "module_order" = excluded."module_order", "order" = excluded."order", "publisher" = excluded."publisher", "review_status" = excluded."review_status", "source_label" = excluded."source_label", "status" = excluded."status", "summary" = excluded."summary", "title" = excluded."title", "topics" = excluded."topics", "url" = excluded."url", "why_here" = excluded."why_here", "year" = excluded."year", "created_date" = excluded."created_date", "updated_date" = excluded."updated_date";
