insert into public.admin_fields (entity, record_id, field, value) values ('LibraryResource', '6acfc09e150c2cf1c514aa60', 'internal_notes', 'Original title: Research Credibility Brief — Entrepalooza / Build Otherwise (2026-09-28). Original review_status: Reference copy only. Preserve the original’s draft/archive status. Source links do not grant cross-workspace access. Check contents for old unsubstantiated pitch stats before any public use.') on conflict (entity, record_id, field) do update set value = excluded.value;
insert into public.library_resource ("audience", "body", "creator", "duration_min", "kind", "lesson_code", "module_order", "order", "publisher", "review_status", "source_label", "status", "summary", "title", "topics", "url", "why_here", "year", "id", "created_date", "updated_date") values ('participant', 'A useful review includes what happened and what it took. Cost can mean time, effort, fatigue, discomfort, or help needed afterward. Finishing a task alone does not show that its conditions are sustainable.
Compare your observation with your explanation. Notice anything else that changed, and keep uncertainty visible.
You choose what to carry into the next module. A brief observation and an unanswered question are enough; you do not need a complete personal profile.', null, null, 'reading', 'M3-L3', 3, 303, null, 'draft', 'Curriculum step M3-L3 — Review what helped and what it cost, from the approved curriculum records.', 'draft', 'Separate the result, the cost and the explanation, then choose what is worth carrying forward.', 'Review what helped and what it cost', '[]'::jsonb, null, 'Separate the result, the cost and the explanation, then choose what is worth carrying forward.', null, '6acfc09e150c2cf1c514aa54', '2026-10-14T17:49:18.235000'::timestamptz, '2026-10-21T20:46:42.920000'::timestamptz) on conflict (id) do update set "audience" = excluded."audience", "body" = excluded."body", "creator" = excluded."creator", "duration_min" = excluded."duration_min", "kind" = excluded."kind", "lesson_code" = excluded."lesson_code", "module_order" = excluded."module_order", "order" = excluded."order", "publisher" = excluded."publisher", "review_status" = excluded."review_status", "source_label" = excluded."source_label", "status" = excluded."status", "summary" = excluded."summary", "title" = excluded."title", "topics" = excluded."topics", "url" = excluded."url", "why_here" = excluded."why_here", "year" = excluded."year", "created_date" = excluded."created_date", "updated_date" = excluded."updated_date";
insert into public.admin_fields (entity, record_id, field, value) values ('LibraryResource', '6acfc09e150c2cf1c514aa54', 'internal_notes', 'ROLE: STEP SUMMARY (backup) — not the participant reading. The lesson card already carries this text; the participant reading for this step is the published Notion-sourced reading with the same lesson_code. Kept for record; do not publish alongside it. Labeled Oct 21, 2026.') on conflict (entity, record_id, field) do update set value = excluded.value;
insert into public.library_resource ("audience", "body", "creator", "duration_min", "kind", "lesson_code", "module_order", "order", "publisher", "review_status", "source_label", "status", "summary", "title", "topics", "url", "why_here", "year", "id", "created_date", "updated_date") values ('participant', '**Development note, not participant-facing.** Future cohorts may need a locally relevant directory of accessible activities, community partners, demonstrations, introductory workshops, and people willing to discuss their work. Verify actual availability, costs, accessibility, and location before offering a specific opportunity. Do not imply a participant can access an experience that has not been arranged.', null, null, 'note', 'M2-L1', 2, 201.5, null, 'published', 'Supplemental note held with curriculum step M2-L1.', 'draft', 'Extra reference material that sits with this step.', 'Exposure Menu — Development Note', '[]'::jsonb, null, 'Extra reference material that sits with this step.', null, '6acfc09e150c2cf1c514aa5d', '2026-10-14T17:49:18.235000'::timestamptz, '2026-10-17T04:22:55.375000'::timestamptz) on conflict (id) do update set "audience" = excluded."audience", "body" = excluded."body", "creator" = excluded."creator", "duration_min" = excluded."duration_min", "kind" = excluded."kind", "lesson_code" = excluded."lesson_code", "module_order" = excluded."module_order", "order" = excluded."order", "publisher" = excluded."publisher", "review_status" = excluded."review_status", "source_label" = excluded."source_label", "status" = excluded."status", "summary" = excluded."summary", "title" = excluded."title", "topics" = excluded."topics", "url" = excluded."url", "why_here" = excluded."why_here", "year" = excluded."year", "created_date" = excluded."created_date", "updated_date" = excluded."updated_date";
insert into public.library_resource ("audience", "body", "creator", "duration_min", "kind", "lesson_code", "module_order", "order", "publisher", "review_status", "source_label", "status", "summary", "title", "topics", "url", "why_here", "year", "id", "created_date", "updated_date") values ('program_team', null, null, null, 'research_brief', null, null, 4, null, 'published', 'Notion · entrepalooza2020 · Evidence Library · page ''Research Alignment — Modules 1.5 & 2 (Oct 6, 2026)''', 'published', 'Checks two modules against the research: looking at the setup around a task, and separating what happened from what it means. These were called Modules 1.5 and 2 in earlier drafts.', 'Research alignment: Modules 3 and 4 (Oct 6, 2026)', '[]'::jsonb, null, 'Checks two modules against the research: looking at the setup around a task, and separating what happened from what it means. These were called Modules 1.5 and 2 in earlier drafts.', null, '6acfc09e150c2cf1c514aa61', '2026-10-14T17:49:18.235000'::timestamptz, '2026-10-14T17:49:18.235000'::timestamptz) on conflict (id) do update set "audience" = excluded."audience", "body" = excluded."body", "creator" = excluded."creator", "duration_min" = excluded."duration_min", "kind" = excluded."kind", "lesson_code" = excluded."lesson_code", "module_order" = excluded."module_order", "order" = excluded."order", "publisher" = excluded."publisher", "review_status" = excluded."review_status", "source_label" = excluded."source_label", "status" = excluded."status", "summary" = excluded."summary", "title" = excluded."title", "topics" = excluded."topics", "url" = excluded."url", "why_here" = excluded."why_here", "year" = excluded."year", "created_date" = excluded."created_date", "updated_date" = excluded."updated_date";
insert into public.admin_fields (entity, record_id, field, value) values ('LibraryResource', '6acfc09e150c2cf1c514aa61', 'internal_notes', 'Original title: Research Alignment — Modules 1.5 & 2 (Oct 6, 2026). Original summary said contents not yet reviewed.') on conflict (entity, record_id, field) do update set value = excluded.value;
insert into public.library_resource ("audience", "body", "creator", "duration_min", "kind", "lesson_code", "module_order", "order", "publisher", "review_status", "source_label", "status", "summary", "title", "topics", "url", "why_here", "year", "id", "created_date", "updated_date") values ('participant', 'After a first experience, the next useful move depends on what you learned. You might explore the same possibility in a different setting, try another part of the work, ask a follow-up question, or look elsewhere.

A decision is not a final judgment about your future. **Keep** means stay with this possibility for now. **Change** means adjust the activity or its conditions. **Test again** means get another experience to compare. **Pause** or **Stop** can fit when the timing or costs are wrong. **Another direction** and **Keep looking** allow exploration to move elsewhere.

Think about what surprised you, what remains unknown, and whether another encounter would add information worth the effort. The choice belongs to you; the workbook does not rank outcomes.', null, null, 'reading', 'M2-L3', 2, 203, null, 'published', 'Curriculum step M2-L3 — Review, next decision, and handoff, from the approved curriculum records.', 'published', 'Review what happened and choose your Next Decision.', 'What Makes a Useful Next Step?', '[]'::jsonb, null, 'Review what happened and choose your Next Decision.', null, '6acfc09e150c2cf1c514aa51', '2026-10-14T17:49:18.235000'::timestamptz, '2026-10-17T04:23:42.992000'::timestamptz) on conflict (id) do update set "audience" = excluded."audience", "body" = excluded."body", "creator" = excluded."creator", "duration_min" = excluded."duration_min", "kind" = excluded."kind", "lesson_code" = excluded."lesson_code", "module_order" = excluded."module_order", "order" = excluded."order", "publisher" = excluded."publisher", "review_status" = excluded."review_status", "source_label" = excluded."source_label", "status" = excluded."status", "summary" = excluded."summary", "title" = excluded."title", "topics" = excluded."topics", "url" = excluded."url", "why_here" = excluded."why_here", "year" = excluded."year", "created_date" = excluded."created_date", "updated_date" = excluded."updated_date";
insert into public.library_resource ("audience", "body", "creator", "duration_min", "kind", "lesson_code", "module_order", "order", "publisher", "review_status", "source_label", "status", "summary", "title", "topics", "url", "why_here", "year", "id", "created_date", "updated_date") values ('participant', 'A value is something that matters to you, such as accuracy or respect. A standard is what that value asks of you in a particular situation. A strategy is one way you try to meet that standard—not the only way. A practice is a small action you can actually observe.
A pressure cue is something you notice before your usual response—for example, seeing a deadline or noticing an urge to rush. You choose the cue; you do not have to create pressure to find one.
A practice plan names the action, an opportunity to try it, limits, and when to stop. A seven-day window is a chance to notice opportunities, not a quota. If no opportunity occurs, record that.

#### What counts as capability evidence

All of these count:

- showing up
- asking for help
- using an accommodation or support
- honoring a boundary
- stopping at a stop rule
- partly completing something
- revising a plan
- returning after a pause
- repairing something
- choosing not to continue
Support, accommodation, and collaboration do not make the evidence less valid.', null, null, 'reading', 'M4-L2', 4, 402, null, 'draft', 'Curriculum step M4-L2 — Turn a chosen value into a small action, from the approved curriculum records.', 'draft', 'Translate a value you choose into one small, observable action with workable limits.', 'Turn a chosen value into a small action', '[]'::jsonb, null, 'Translate a value you choose into one small, observable action with workable limits.', null, '6acfc09e150c2cf1c514aa59', '2026-10-14T17:49:18.235000'::timestamptz, '2026-10-21T20:46:42.920000'::timestamptz) on conflict (id) do update set "audience" = excluded."audience", "body" = excluded."body", "creator" = excluded."creator", "duration_min" = excluded."duration_min", "kind" = excluded."kind", "lesson_code" = excluded."lesson_code", "module_order" = excluded."module_order", "order" = excluded."order", "publisher" = excluded."publisher", "review_status" = excluded."review_status", "source_label" = excluded."source_label", "status" = excluded."status", "summary" = excluded."summary", "title" = excluded."title", "topics" = excluded."topics", "url" = excluded."url", "why_here" = excluded."why_here", "year" = excluded."year", "created_date" = excluded."created_date", "updated_date" = excluded."updated_date";
insert into public.admin_fields (entity, record_id, field, value) values ('LibraryResource', '6acfc09e150c2cf1c514aa59', 'internal_notes', 'ROLE: STEP SUMMARY (backup) — not the participant reading. The lesson card already carries this text; the participant reading for this step is the published Notion-sourced reading with the same lesson_code. Kept for record; do not publish alongside it. Labeled Oct 21, 2026.') on conflict (entity, record_id, field) do update set value = excluded.value;
insert into public.library_resource ("audience", "body", "creator", "duration_min", "kind", "lesson_code", "module_order", "order", "publisher", "review_status", "source_label", "status", "summary", "title", "topics", "url", "why_here", "year", "id", "created_date", "updated_date") values ('participant', 'A signal is a change you notice in your body, attention, pace, or energy. It might involve speeding up, slowing down, tension, tiredness, or difficulty staying with a task. Noticing a signal does not tell you its cause.
A story is the meaning you attach to the signal or situation. An urge is what you feel pulled to do or avoid. Your usual action is what you commonly do next. Cost is what that action takes from you or others, such as time, effort, energy, or an interrupted responsibility.
The sequence is signal → story → urge → usual action → cost. It is a way to separate observations, not a rule that everyone experiences all five in a neat order. Any part can be absent or unknown.
The aim is to keep a choice available. Calmness is not a completion requirement. You can notice both urgency and slowing down without diagnosing either.', null, null, 'reading', 'M5-L1', 5, 501, null, 'draft', 'Curriculum step M5-L1 — Understand the sequence before you map it, from the approved curriculum records.', 'draft', 'Tell the five parts apart and find one point where a choice or pause could be available.', 'Understand the sequence before you map it', '[]'::jsonb, null, 'Tell the five parts apart and find one point where a choice or pause could be available.', null, '6acfc09e150c2cf1c514aa5c', '2026-10-14T17:49:18.235000'::timestamptz, '2026-10-21T20:46:42.920000'::timestamptz) on conflict (id) do update set "audience" = excluded."audience", "body" = excluded."body", "creator" = excluded."creator", "duration_min" = excluded."duration_min", "kind" = excluded."kind", "lesson_code" = excluded."lesson_code", "module_order" = excluded."module_order", "order" = excluded."order", "publisher" = excluded."publisher", "review_status" = excluded."review_status", "source_label" = excluded."source_label", "status" = excluded."status", "summary" = excluded."summary", "title" = excluded."title", "topics" = excluded."topics", "url" = excluded."url", "why_here" = excluded."why_here", "year" = excluded."year", "created_date" = excluded."created_date", "updated_date" = excluded."updated_date";
insert into public.admin_fields (entity, record_id, field, value) values ('LibraryResource', '6acfc09e150c2cf1c514aa5c', 'internal_notes', 'ROLE: STEP SUMMARY (backup) — not the participant reading. The lesson card already carries this text; the participant reading for this step is the published Notion-sourced reading with the same lesson_code. Kept for record; do not publish alongside it. Labeled Oct 21, 2026.') on conflict (entity, record_id, field) do update set value = excluded.value;
insert into public.library_resource ("audience", "body", "creator", "duration_min", "kind", "lesson_code", "module_order", "order", "publisher", "review_status", "source_label", "status", "summary", "title", "topics", "url", "why_here", "year", "id", "created_date", "updated_date") values ('participant', 'An intuition is an impression or hunch. It can suggest a question, but it is not the same as evidence. Check what supports it, what challenges it, and what you do not yet know. This is the same move as before: keep what you observed separate from what you make of it.
A decision rule states what information will guide your next choice. A protected boundary names a limit you want to keep. The next step can be a question to investigate rather than a business idea or commitment.', null, null, 'reading', 'M5-L3', 5, 503, null, 'draft', 'Curriculum step M5-L3 — Check an impression and close Pilot 1, from the approved curriculum records.', 'draft', 'Separate impression from evidence, choose a decision rule and a protected boundary, and take stock at the halfway point with what you choose to keep.', 'Check an impression and take stock', '[]'::jsonb, null, 'Separate impression from evidence, choose a decision rule and a protected boundary, and close Pilot 1 with what you choose to keep.', null, '6acfc09e150c2cf1c514aa5a', '2026-10-14T17:49:18.235000'::timestamptz, '2026-10-21T20:53:27.714000'::timestamptz) on conflict (id) do update set "audience" = excluded."audience", "body" = excluded."body", "creator" = excluded."creator", "duration_min" = excluded."duration_min", "kind" = excluded."kind", "lesson_code" = excluded."lesson_code", "module_order" = excluded."module_order", "order" = excluded."order", "publisher" = excluded."publisher", "review_status" = excluded."review_status", "source_label" = excluded."source_label", "status" = excluded."status", "summary" = excluded."summary", "title" = excluded."title", "topics" = excluded."topics", "url" = excluded."url", "why_here" = excluded."why_here", "year" = excluded."year", "created_date" = excluded."created_date", "updated_date" = excluded."updated_date";
insert into public.admin_fields (entity, record_id, field, value) values ('LibraryResource', '6acfc09e150c2cf1c514aa5a', 'internal_notes', 'ROLE: STEP SUMMARY (backup) — not the participant reading. Oct 21, 2026: retitled from ''Check an impression and close Pilot 1'' to match the lesson card; Module 5 is a halfway take-stock (Oct 14 decision), not a close. Source label left as the original record name for auditability.') on conflict (entity, record_id, field) do update set value = excluded.value;
insert into public.library_resource ("audience", "body", "creator", "duration_min", "kind", "lesson_code", "module_order", "order", "publisher", "review_status", "source_label", "status", "summary", "title", "topics", "url", "why_here", "year", "id", "created_date", "updated_date") values ('participant', 'Start with an activity from your own week when you have one. The examples show the two routes. They are not a second assignment.

Tuning, in this lesson, means one of two equal choices: leave a working setup alone, or change one thing. You are not fixing yourself.

Once you have noticed what is happening, there are two legitimate directions.

Something may be working.

Or something may need attention.

Neither route is more successful than the other.

---

#### Keep what is in tune

Suppose you are deeply engaged in something and the current setup is working.

You can still stop.

You can adjust when needed.

Important responsibilities are not being pushed out.

The pace feels sustainable enough for you.

You have support where you need it.

There is no rule saying you must interfere.

Instead, ask:

What is helping this stay workable?

Maybe it is:

- having a clear stopping point
- enough freedom to make decisions
- clear expectations
- another person available for support
- protected time
- a manageable pace
- breaks
- limited spending
- keeping another responsibility intact
- knowing that you are allowed to stop

Research on passion suggests that more autonomous forms of engagement are associated with more adaptive outcomes than more pressured and rigid forms of passion.

Some research has also linked autonomy-supportive environments with the development of more harmonious passion, although parts of that evidence come from younger samples and do not prove that changing one condition will transform a person''s passion.

So we stay modest.

If something appears to support flexible, chosen engagement:

notice it and decide whether you want to protect it.

#### Protecting something is an action too

People often pay more attention to problems than to working conditions.

Then a useful condition disappears because nobody thought to protect it.

Imagine that you discover:

“I enjoy doing this when I stop at two hours.”

You do not necessarily need a new strategy.

Your strategy may be:

Keep the two-hour boundary.

Or:

“I work well on this when I have one evening completely free afterward.”

Protecting that recovery time may matter.

Leaving a working setup alone still requires decisions.

It just does not require a crisis first.

---

#### Change one thing

Maybe you notice something different.

Pressure keeps rising.

You cannot stop when you intended to.

A responsibility is getting pushed aside.

The activity is costing more money, time, energy, or recovery than you expected.

You find yourself continuing mostly because stopping feels unacceptable.

Or an outside barrier is making the current approach unworkable.

Now the question becomes:

Where is one possible choice point?

Not:

“How do I control every reaction?”

Just:

“What is one practical thing I could change?”

#### One response, not an overhaul

A response might be:

- clarify one instruction
- write down one next action
- make the task smaller
- add a stopping point
- ask for specific help
- protect an existing responsibility
- remove one manageable distraction
- change the environment
- take a planned break
- stop safely
- return another time under different conditions

Research on emotion regulation gives us an important caution here.

There is not one strategy that is universally best in every situation.

Researchers studying regulatory flexibility have argued that what works depends partly on the person, the situation, the options available, and what happens after a strategy is used.

So this module does not teach:

“Whenever intensity rises, always do X.”

It teaches:

notice → choose a reasonable response → watch what happens.

#### Choose what you are protecting

Before making the change, ask:

What must not get bulldozed while I pursue this?

Maybe:

“My sleep.”

“Picking up my kid.”

“My rent money.”

“A relationship.”

“My recovery time.”

“Another responsibility.”

“My ability to stop.”

“My physical safety.”

“My privacy.”

The protected boundary is an Entrepalooza curriculum tool.

Research did not hand us a universal list of boundaries.

The point of the tool is to make an important limit visible before intensity makes the decision for you.

#### Then look at the result

If you try a response, notice:

Did the next choice become easier?

Harder?

Unchanged?

Unclear?

What did the response require?

What happened afterward?

What else may have influenced the result?

One attempt does not prove the response works universally.

It gives you another piece of evidence.

#### You can also choose not to try

Maybe the response is not appropriate.

Maybe the barrier cannot be changed right now.

Maybe you need support first.

Maybe you want to stop instead.

Maybe continuing no longer makes sense.

Changing one thing does not secretly mean:

“Find a strategy that keeps you going.”

Stopping and redirecting count here too.

#### Carry this question forward

What is working that I want to protect, or what is one choice I could change without sacrificing something important?', null, null, 'reading', 'M5-L2', 5, 110, null, 'published', 'Notion Module 3 (working replacement draft, copy of Oct 6, 2026), Reading 2, in the source''s own words.', 'published', null, 'Keep What Is in Tune, or Change One Thing', '[]'::jsonb, null, null, null, '6acfc09e150c2cf1c514aa6c', '2026-10-14T17:49:18.235000'::timestamptz, '2026-10-20T03:23:25.865000'::timestamptz) on conflict (id) do update set "audience" = excluded."audience", "body" = excluded."body", "creator" = excluded."creator", "duration_min" = excluded."duration_min", "kind" = excluded."kind", "lesson_code" = excluded."lesson_code", "module_order" = excluded."module_order", "order" = excluded."order", "publisher" = excluded."publisher", "review_status" = excluded."review_status", "source_label" = excluded."source_label", "status" = excluded."status", "summary" = excluded."summary", "title" = excluded."title", "topics" = excluded."topics", "url" = excluded."url", "why_here" = excluded."why_here", "year" = excluded."year", "created_date" = excluded."created_date", "updated_date" = excluded."updated_date";
