insert into public.admin_fields (entity, record_id, field, value) values ('LibraryResource', '6acfc09e150c2cf1c514aa73', 'internal_notes', 'ROLE: OPTIONAL outside source for M5-L1 (Dualistic Model of Passion). Moved from Module 1 on Oct 21, 2026 to match the Oct 19 move of the DMP explanation into the Module 5 reading ''Intensity Is Not Automatically the Problem''. Original note: Added by Claude, Oct 12 2026 — awaiting Ashley''s approval.') on conflict (entity, record_id, field) do update set value = excluded.value;
insert into public.library_resource ("audience", "body", "creator", "duration_min", "kind", "lesson_code", "module_order", "order", "publisher", "review_status", "source_label", "status", "summary", "title", "topics", "url", "why_here", "year", "id", "created_date", "updated_date") values ('participant', '**Quick teach-back (60–90 seconds, aloud, in writing, or privately):** *Name one thing this program will not do. Name how you’d pause or leave.*
**The words we’ll use all program long** for any next decision: **Keep · Change · Test again · Pause · Stop · Another direction · Keep looking.** Every one is a legitimate choice. Keep looking counts when you name what’s unknown and when you’ll look again.', null, null, 'reading', 'O.5', 0, 5, null, 'published', 'Curriculum step O.5 — Your participation decision and handoff, from the approved curriculum records.', 'draft', 'Decide freely whether and how to take part.', 'Your participation decision and handoff', '[]'::jsonb, null, 'Decide freely whether and how to take part.', null, '6acfc09e150c2cf1c514aa4a', '2026-10-14T17:49:18.234000'::timestamptz, '2026-10-21T20:53:12.353000'::timestamptz) on conflict (id) do update set "audience" = excluded."audience", "body" = excluded."body", "creator" = excluded."creator", "duration_min" = excluded."duration_min", "kind" = excluded."kind", "lesson_code" = excluded."lesson_code", "module_order" = excluded."module_order", "order" = excluded."order", "publisher" = excluded."publisher", "review_status" = excluded."review_status", "source_label" = excluded."source_label", "status" = excluded."status", "summary" = excluded."summary", "title" = excluded."title", "topics" = excluded."topics", "url" = excluded."url", "why_here" = excluded."why_here", "year" = excluded."year", "created_date" = excluded."created_date", "updated_date" = excluded."updated_date";
insert into public.library_resource ("audience", "body", "creator", "duration_min", "kind", "lesson_code", "module_order", "order", "publisher", "review_status", "source_label", "status", "summary", "title", "topics", "url", "why_here", "year", "id", "created_date", "updated_date") values ('participant', '“Passing on a personal question does not require an explanation.”
Participants have rights to: choose what they share, pass without defending the choice, ask who can see stored information, request correction, and raise a concern—including through an alternative route when the concern involves the facilitator (once that route is confirmed).
Program participation, evaluation, recording, publicity/story use, and follow-up are **separate** choices. Saying yes to one does not mean yes to the others. This lesson’s discussion sheet is not a substitute legal consent form—use the program’s adopted consent documents when those are available.
Do not collect addiction, legal, or diagnostic histories to prove eligibility here.', null, null, 'reading', 'O.2', 0, 2, null, 'published', 'Curriculum step O.2 — Rights, privacy, and separate consent, from the approved curriculum records.', 'draft', 'Identify participation rights, the actual privacy limits, correction routes, and separate consent choices.', 'Rights, privacy, and separate consent', '[]'::jsonb, null, 'Identify participation rights, the actual privacy limits, correction routes, and separate consent choices.', null, '6acfc09e150c2cf1c514aa4d', '2026-10-14T17:49:18.234000'::timestamptz, '2026-10-15T03:02:47.891000'::timestamptz) on conflict (id) do update set "audience" = excluded."audience", "body" = excluded."body", "creator" = excluded."creator", "duration_min" = excluded."duration_min", "kind" = excluded."kind", "lesson_code" = excluded."lesson_code", "module_order" = excluded."module_order", "order" = excluded."order", "publisher" = excluded."publisher", "review_status" = excluded."review_status", "source_label" = excluded."source_label", "status" = excluded."status", "summary" = excluded."summary", "title" = excluded."title", "topics" = excluded."topics", "url" = excluded."url", "why_here" = excluded."why_here", "year" = excluded."year", "created_date" = excluded."created_date", "updated_date" = excluded."updated_date";
insert into public.admin_fields (entity, record_id, field, value) values ('LibraryResource', '6acfc09e150c2cf1c514aa4d', 'internal_notes', '

Founder-requested journal policy overlay from current conversation: minimum one short saved note per associated lesson. Original reading above retained; appended app-policy note is not attributed to the original source. No status or consent changes.') on conflict (entity, record_id, field) do update set value = excluded.value;
insert into public.library_resource ("audience", "body", "creator", "duration_min", "kind", "lesson_code", "module_order", "order", "publisher", "review_status", "source_label", "status", "summary", "title", "topics", "url", "why_here", "year", "id", "created_date", "updated_date") values ('participant', 'The **Participation and Support Plan** is short, private, and every line is optional:

- **How I like to take part:** aloud · in writing · privately · observing
- **Access needs:** reading or language support, hearing or vision, seating or mobility, breaks, schedule
- **Technology limits:** device, data, offline or paper options
- **Life logistics:** childcare, transportation, work shifts
- **Support I’d want:** none is a fine answer
- **Where I’d raise a concern:** the confirmed route (or “not yet confirmed”)
- **Optional starting question:** something you’re curious about. “I don’t know yet” is welcome.
We don’t ask for diagnoses, addiction, legal, or medical histories.', null, null, 'reading', 'O.4', 0, 4, null, 'published', 'Curriculum step O.4 — Participation and Support Plan, from the approved curriculum records.', 'draft', 'Name the conditions that make participation workable, without disclosing anything you don''t want to.', 'Participation and Support Plan', '[]'::jsonb, null, 'Name the conditions that make participation workable, without disclosing anything you don''t want to.', null, '6acfc09e150c2cf1c514aa4b', '2026-10-14T17:49:18.234000'::timestamptz, '2026-10-15T03:02:47.891000'::timestamptz) on conflict (id) do update set "audience" = excluded."audience", "body" = excluded."body", "creator" = excluded."creator", "duration_min" = excluded."duration_min", "kind" = excluded."kind", "lesson_code" = excluded."lesson_code", "module_order" = excluded."module_order", "order" = excluded."order", "publisher" = excluded."publisher", "review_status" = excluded."review_status", "source_label" = excluded."source_label", "status" = excluded."status", "summary" = excluded."summary", "title" = excluded."title", "topics" = excluded."topics", "url" = excluded."url", "why_here" = excluded."why_here", "year" = excluded."year", "created_date" = excluded."created_date", "updated_date" = excluded."updated_date";
insert into public.admin_fields (entity, record_id, field, value) values ('LibraryResource', '6acfc09e150c2cf1c514aa4b', 'internal_notes', '

Founder-requested journal policy overlay from current conversation: minimum one short saved note per associated lesson. Original reading above retained; appended app-policy note is not attributed to the original source. No status or consent changes.') on conflict (entity, record_id, field) do update set value = excluded.value;
insert into public.library_resource ("audience", "body", "creator", "duration_min", "kind", "lesson_code", "module_order", "order", "publisher", "review_status", "source_label", "status", "summary", "title", "topics", "url", "why_here", "year", "id", "created_date", "updated_date") values ('participant', 'Getting Started · Step 1 of 5 · About 10 min

#### What this is (and isn''t)

Know what this pilot will and won''t do before you decide anything.
Type into any answer box, or use the Dictate button beside that box. You can use your keyboard’s microphone too.

#### 1. What this is

You can reflect in writing, talk through a question, or combine both. Skipping a personal question never needs a reason.
**This pilot is:**

- a way to notice what holds your attention, try something small, think about how it went, and decide what''s next
- a group that learns together
- a place where a job, training, a project, a pause, or still looking all count as finishing
**This pilot isn''t:**
- therapy or treatment
- a promise of a job, income, or business success
- a test of whether you''re "ready"
- a place where you have to tell your story
- a business program
Entrepreneurship is optional here.
Tap any line to save it. You can add a thought next to it if you want.

#### 2. See the example

In one group, Jess picked a training class. Marcus took a break for a while. Dee tried selling candles. All three finished.

#### 3. Answer directly

Each answer box has its own Dictate button. You can type, dictate, or combine both. You can skip a question.

#### 4. Try

Name one thing this program won''t do. Or pass.
Optional: suggest a name for your group.

#### 5. Reflect

What''s clearer now?
What do you still want to ask?

#### 6. What''s next for you?

- Keep going
- Pause
- I don''t know yet
All three are complete answers.

#### 7. Wrapping up

One line anywhere on this page counts. Short counts the same as long. "I don''t know yet" counts too.

---', null, null, 'reading', 'O.1', 0, 1, null, 'published', 'Curriculum step O.1 — What this pilot is and isn''t, from the approved curriculum records.', 'draft', 'Know what this pilot will and won''t do before you decide anything.', 'What this pilot is and isn''t', '[]'::jsonb, null, 'Know what this pilot will and won''t do before you decide anything.', null, '6acfc09e150c2cf1c514aa4e', '2026-10-14T17:49:18.234000'::timestamptz, '2026-10-19T01:27:29.815000'::timestamptz) on conflict (id) do update set "audience" = excluded."audience", "body" = excluded."body", "creator" = excluded."creator", "duration_min" = excluded."duration_min", "kind" = excluded."kind", "lesson_code" = excluded."lesson_code", "module_order" = excluded."module_order", "order" = excluded."order", "publisher" = excluded."publisher", "review_status" = excluded."review_status", "source_label" = excluded."source_label", "status" = excluded."status", "summary" = excluded."summary", "title" = excluded."title", "topics" = excluded."topics", "url" = excluded."url", "why_here" = excluded."why_here", "year" = excluded."year", "created_date" = excluded."created_date", "updated_date" = excluded."updated_date";
insert into public.admin_fields (entity, record_id, field, value) values ('LibraryResource', '6acfc09e150c2cf1c514aa4e', 'internal_notes', '

Founder-requested journal policy overlay from current conversation: minimum one short saved note per associated lesson. Original reading above retained; appended app-policy note is not attributed to the original source. No status or consent changes.') on conflict (entity, record_id, field) do update set value = excluded.value;
insert into public.library_resource ("audience", "body", "creator", "duration_min", "kind", "lesson_code", "module_order", "order", "publisher", "review_status", "source_label", "status", "summary", "title", "topics", "url", "why_here", "year", "id", "created_date", "updated_date") values ('participant', 'Intensity can support meaning and effort, but it can also become rigid, controlling, or costly. The useful question is not whether passion is good or bad. It is how your relationship with an activity is working right now.

- **Obsessive pattern:** An activity starts to feel controlling, rigid, pressured, or tied to self-worth. It gets hard to stop, adjust, or fit alongside health, relationships, responsibilities, rest, and support.
- **Harmonious pattern:** An activity matters deeply and still feels chosen and flexible, and it fits alongside the other important parts of life. Harmonious does not mean weak, effortless, or free of difficulty.
**Say this out loud:** “These are patterns of relating to an activity, not types of people. Mixed and unclear are complete answers. Patterns can shift with conditions over time; this module does not diagnose or convert anyone’s passion.”', null, null, 'reading', 'M5-L1', 5, 501.9, null, 'draft', 'Curriculum step M1-L2 — Obsessive and harmonious patterns (not labels), from the approved curriculum records.', 'draft', 'Learn two patterns of relating to an activity as noticing tools, not types of people.', 'Obsessive and harmonious patterns (not labels)', '[]'::jsonb, null, 'Learn two patterns of relating to an activity as noticing tools, not types of people.', null, '6acfc09e150c2cf1c514aa4f', '2026-10-14T17:49:18.234000'::timestamptz, '2026-10-21T20:46:42.920000'::timestamptz) on conflict (id) do update set "audience" = excluded."audience", "body" = excluded."body", "creator" = excluded."creator", "duration_min" = excluded."duration_min", "kind" = excluded."kind", "lesson_code" = excluded."lesson_code", "module_order" = excluded."module_order", "order" = excluded."order", "publisher" = excluded."publisher", "review_status" = excluded."review_status", "source_label" = excluded."source_label", "status" = excluded."status", "summary" = excluded."summary", "title" = excluded."title", "topics" = excluded."topics", "url" = excluded."url", "why_here" = excluded."why_here", "year" = excluded."year", "created_date" = excluded."created_date", "updated_date" = excluded."updated_date";
insert into public.admin_fields (entity, record_id, field, value) values ('LibraryResource', '6acfc09e150c2cf1c514aa4f', 'internal_notes', 'ROLE: STEP SUMMARY (backup) — not the participant reading. The lesson card already carries this text; the participant reading for this step is the published Notion-sourced reading with the same lesson_code. Kept for record; do not publish alongside it. Labeled Oct 21, 2026.') on conflict (entity, record_id, field) do update set value = excluded.value;
insert into public.library_resource ("audience", "body", "creator", "duration_min", "kind", "lesson_code", "module_order", "order", "publisher", "review_status", "source_label", "status", "summary", "title", "topics", "url", "why_here", "year", "id", "created_date", "updated_date") values ('participant', '*Place before Lesson 1: Notice without forcing an answer. The map produces participant-selected evidence from actual life before anyone is asked to choose a direction.*
**Purpose:** Notice what already occupies your time, attention, energy, movement, and relationships before deciding what might be worth exploring.
**Time:** 25–35 minutes · **Materials:** Blank paper or digital canvas, pen/marker · **Output:** One life map + one thing worth looking at more closely

### Start here

You do not need to know what you want to do with your life.
You do not need a business idea.
You do not need to identify your "passion."
For this exercise, we are starting somewhere more concrete:
What does your life actually look like right now?
Researchers call a version of this **occupational mapping**. Instead of relying only on an interview or questionnaire, people draw the places they go and talk about what they actually do there. That can bring out ordinary routines, relationships, barriers, and meaningful activities that are easy to leave out when somebody simply asks, "Tell me about yourself."
Your map does not need to look good.
This is not art class.
Boxes, circles, arrows, words, stick figures, scribbles and mildly questionable geography are all legal.

### Part 1: Draw your week

Put HOME somewhere on the page.
Now think about a normal week.
Add the places you regularly go.
They could include:

- work
- someone else''s house
- school
- stores
- a gym
- church
- meetings
- appointments
- parks
- restaurants
- a garage
- a friend''s place
- treatment or recovery spaces
- community organizations
- places connected to your kids
- anywhere else that is actually part of your life
Connect the places however makes sense to you.
Then add what you usually do there.
You are not trying to make a geographically accurate map. You''re making a map of your lived week.
This closely follows the research method, where participants were asked to show the places they went during a typical week and weekend, describe what those places were, how they got there, and what they did once they arrived.

### Part 2: Add the things that don''t have a place

Some important parts of life happen without going anywhere.
Add those too.
Maybe you:

- research something for hours from your phone
- fix things
- draw
- game
- cook
- sell things online
- talk people through problems
- scroll
- write
- care for somebody
- organize things
- watch tutorials
- work on a car
- make music
- argue on Reddit about something you accidentally became an expert in
- spend three hours researching something nobody asked you to research
Put them somewhere on the page.
The 2020 occupational-mapping study found exactly this problem: activities such as job searching sometimes disappeared from participants'' physical maps because they happened online from home, libraries, or service organizations.
So don''t let "I didn''t go anywhere" turn into "I didn''t do anything."

### Part 3: Mark the energy

Look over your map.
Don''t analyze it yet.
Just mark it.
Use whatever symbols you want.

| Symbol | Meaning |
| --- | --- |
| + | gives me energy |
| – | drains me |
| * | I care about this |
| ? | I''m curious about this |
| $ | mostly because I need money/resources |
| ! | I get unusually focused here |
| X | something gets in the way |

You can invent your own symbols.
There is no scoring system.

### Part 4: Look at what''s missing

Now look at the blank spaces.
Ask yourself:

- What used to be part of my life that isn''t anymore?
- What do I want to do but rarely get access to?
- Where would I go if money, transportation, time, childcare, fear, paperwork, health, or another barrier weren''t stopping me?
- Who or what would be on this map if my circumstances were different?
Write those things outside the edge of the map.
That distinction matters.
Sometimes something is missing because you don''t care about it.
Sometimes it''s missing because you can''t currently reach it.
Those are not the same thing.
Research using occupational maps found that access to transportation, money, services, social expectations, and other resources could substantially shape where people went and what they were able to do.

### Part 5: Find the threads

Now stop looking at individual places.
Look for patterns.
Finish any of these that actually fit:

- I keep ending up around…
- I spend more time than I realized doing…
- People seem to come to me for…
- I lose track of time when…
- I keep researching…
- I seem to know a weird amount about…
- I keep trying to improve…
- I get frustrated when…
- Something I miss is…
- Something I wish I had access to is…
- One part of this map I would willingly make bigger is…
You do not have to answer every prompt.

### Part 6: Pick one thing worth exploring

You are not choosing a career.
You are not committing to a business.
You are not announcing your life''s purpose.
Pick one thread that makes you curious enough to look again.
Complete:
**One thing I might want to understand better is:**
**I noticed it because:**
**I do NOT know yet:**
**One small way I could learn more about it:**
That''s enough.
Your answer can change.

### Before you leave the lesson

Your map may show something exciting.
It may show survival.
It may look crowded, repetitive, tiny, chaotic, boring, disconnected, or unfinished.
Do not grade the map.
In the long-term unemployment study, participants'' daily movement and occupations differed substantially depending on resources, transportation, social connection, employment circumstances, and other constraints. The researchers used mapping to make those circumstances more visible, not to rank people.
The map is evidence.
It says:
This is where my life is right now.
Then we can ask a better question:
What here might be worth testing?

### Participant controls

You may:

- keep the whole map private
- share only one section
- describe it without showing it
- leave something off intentionally
- stop and return later
- decide that nothing on the map is worth exploring yet
You do not have to turn the most painful, intense, or personal part of your life into a project.

### Facilitator note

Do not interpret the participant''s map for them.
Avoid:

> "Your map shows that you''re isolated."
>

Use:

> "What do you notice?"
>

Avoid:

> "Clearly you''re passionate about cars."
>

Use:

> "You marked that in three different places. Does that mean anything to you?"
>

The research treats the map and the participant''s explanation together. The visual alone is not supposed to speak for the person who made it.
And because participants choose what to include, visual methods can give them greater control over what becomes part of the conversation.

### Carry forward

One participant-selected thread worth looking at more closely — or "nothing on the map is worth exploring yet," which counts as a complete answer. Feeds Lesson 1''s **Try—or pass** selection.

### The Entrepalooza rule

Notice before naming.
Evidence before identity.
Explore before committing.
That makes this a strong lead-in to Module 1''s next move: taking one of those threads and running a small, bounded experiment instead of deciding what somebody "should become."', null, null, 'reading', 'O.6', 0, 6, null, 'published', 'Curriculum step O.6 — Map the Life You''re Actually Living, from the approved curriculum records.', 'draft', 'Put the life you are actually living on one page, before you plan anything.', 'Map the Life You''re Actually Living', '[]'::jsonb, null, 'Put the life you are actually living on one page, before you plan anything.', null, '6acfc09e150c2cf1c514aa49', '2026-10-14T17:49:18.234000'::timestamptz, '2026-10-15T04:31:25.528000'::timestamptz) on conflict (id) do update set "audience" = excluded."audience", "body" = excluded."body", "creator" = excluded."creator", "duration_min" = excluded."duration_min", "kind" = excluded."kind", "lesson_code" = excluded."lesson_code", "module_order" = excluded."module_order", "order" = excluded."order", "publisher" = excluded."publisher", "review_status" = excluded."review_status", "source_label" = excluded."source_label", "status" = excluded."status", "summary" = excluded."summary", "title" = excluded."title", "topics" = excluded."topics", "url" = excluded."url", "why_here" = excluded."why_here", "year" = excluded."year", "created_date" = excluded."created_date", "updated_date" = excluded."updated_date";
insert into public.library_resource ("audience", "body", "creator", "duration_min", "kind", "lesson_code", "module_order", "order", "publisher", "review_status", "source_label", "status", "summary", "title", "topics", "url", "why_here", "year", "id", "created_date", "updated_date") values ('participant', 'The working Group Code (also called the Builder’s Code; packet **P0.2**) is a group agreement, not a loyalty pledge. You don’t have to call yourself a builder to use it:

- Ask before giving advice, challenging an interpretation, or sharing someone’s work.
- Respect “no,” “not now,” passing, and changing one’s mind.
- Speak about an action or piece of evidence; do not diagnose or assign an identity.
- Do not repeat someone’s personal story or record/photograph them without specific permission.
- Offer only support you can actually provide. No fixing, rescuing, policing, or private-life monitoring.
- Use the program’s concern route when a boundary is crossed.
Acknowledgment means the agreements were reviewed—not that someone surrendered rights. Majority preference cannot remove the right to pass or privacy protections.', null, null, 'reading', 'O.3', 0, 3, null, 'published', 'Curriculum step O.3 — Group Code (Builder''s Code) and permission-based feedback, from the approved curriculum records.', 'draft', 'Practise giving, receiving, declining and revising feedback without pressure.', 'Group Code (Builder''s Code) and permission-based feedback', '[]'::jsonb, null, 'Practise giving, receiving, declining and revising feedback without pressure.', null, '6acfc09e150c2cf1c514aa4c', '2026-10-14T17:49:18.234000'::timestamptz, '2026-10-15T03:02:47.891000'::timestamptz) on conflict (id) do update set "audience" = excluded."audience", "body" = excluded."body", "creator" = excluded."creator", "duration_min" = excluded."duration_min", "kind" = excluded."kind", "lesson_code" = excluded."lesson_code", "module_order" = excluded."module_order", "order" = excluded."order", "publisher" = excluded."publisher", "review_status" = excluded."review_status", "source_label" = excluded."source_label", "status" = excluded."status", "summary" = excluded."summary", "title" = excluded."title", "topics" = excluded."topics", "url" = excluded."url", "why_here" = excluded."why_here", "year" = excluded."year", "created_date" = excluded."created_date", "updated_date" = excluded."updated_date";
insert into public.lesson_review_package ("instructional_purpose", "lesson_code", "lesson_id", "reviewer_notes", "research_rationale", "proposed_draft_text", "decision_note", "decided_date", "source_label", "facilitator_boundaries", "source_url", "module_title", "lesson_title", "current_card_note", "review_scope", "review_status", "approval_decision", "approved_version", "research_limitations", "internal_notes", "module_order", "participation_alternatives", "approver", "changes_requested", "source_date", "proposed_draft_label", "id", "created_date", "updated_date") values ('Help participants test internal assumptions against ethical, accessible information from the outside world. Everyone learns a shared evidence-checking method and then chooses a pathway, problem/opportunity, or continued-exploration branch.
Module 4 begins with a question—not a pitch. It does not require a business idea, direct interview, customer, market, unmet need, offer, or progression to Module 5.', 'M6-L3', '6acfad71713aa2815e104ecb', 'Tribe thread: Peer feedback lab on evidence labels (observation vs assumption). Honest peer screening > cheerleading. No extracting free research from vulnerable people.

Proposed prompts inside the draft text are recommendations for review, not approved participant instructions.', 'Research: See sibling Research Brief — All Modules under this Live Curriculum parent. Key cites (analogous): Sarasvathy 2001 effectuation · Leatherbee & Katila 2020 · Kolb experiential learning. Equal branches; no validate/demand claims.', 'Pathway branch
Possible questions:
- What does this field or activity actually involve?
- What environments, schedules, skills, credentials, costs, or supports are typical?
- What do people doing this work wish they had known?
- What accessible first exposure could test fit?
- Which barriers are practical, structural, or resource-related?
Potential methods include reviewing actual requirements and costs, observing a setting, completing a beginner task, attending a class sample, visiting a program, or having an informational conversation.

Problem/opportunity branch
Look for:
- Friction and repeated confusion
- Workarounds
- Delays or unnecessary cost
- Missing access
- Mistakes or tolerated problems
- Existing solutions and community assets
- Who experiences the issue and under what conditions
- Who benefits and who carries cost
- Whose perspective is missing
The output is opportunity evidence—not a market verdict.

Continued-exploration branch
Participants may:
- Compare two or more possibilities
- Gather broad field information
- Repeat a small exposure experiment
- Identify what they still need to experience
- Pause or return later
No direction needs to be selected.

What comes out
One branch-specific evidence note and one open question.', '', null, 'Notion — Entrepalooza Curriculum & Evidence Lab · Module 4 working draft · Copy of Ashley Zeck workspace original · Oct 6, 2026 · edits here do not sync. Cross-links may still point to Ashley-workspace originals until rewritten.', '- Do not steer participants toward business ownership.
- Do not treat all friction as an opportunity to monetize.
- Keep structural and practical barriers visible.
- Do not require cold outreach, travel, spending, public disclosure, or direct interviews.
- Do not describe one example as validation.
- Ask whose perspective is missing and who may bear cost.
- Preserve participant choice to park, stop, redirect, or continue looking.

- Do not ask vulnerable people for trauma stories, unpaid emotional labor, or free consulting.
- Do not present a learning conversation as formal research, treatment, employment, partnership, or a promised solution.
- Ask permission before taking notes, quoting, recording, or sharing information.
- Do not collect identifying or sensitive information without an approved process.
- Accept no, nonresponse, cancellation, and limited access as real outcomes.
- Use public, neutral, or simulated routes when direct contact is inappropriate or inaccessible.
- Do not treat one conversation as proof of demand, prevalence, or validation.
- Do not assume every observed problem should become a business opportunity.', 'https://www.notion.so/3f1ca793c2c5819c948ff3bbcc283ddb', 'Check Reality Outside Yourself', 'Choose a branch and investigate', 'Existing card retained unchanged, as structure. Teaching on this card is not approved for participant delivery.', 'Outside questions, evidence gathering, relevant branches, and personal fit versus actual availability.', 'pending_evaluator_and_clinical_review', '', '', 'Research and theory are used as design lenses, not as proof that Entrepalooza works. Related research does not prove that Entrepalooza works.', '', 6, 'Pass, respond in private, observe, pause, stop, or choose another direction.
A missing worksheet is not a failed module.
Every decision fits one of these labels: Keep, Change, Test Again, Pause/Park, Stop, Another Direction, Continue Looking. "Still don''t know" lives under Continue Looking.', '', 'Status: Working replacement draft for review and rehearsal. The current Module 4 lesson pages remain unchanged until this draft is approved. This draft provides a shared evidence foundation followed by pathway, problem/opportunity, and continued-exploration branches.', 'Oct 6, 2026', 'Review candidate — working replacement draft. Not approved teaching, and not part of the participant workbook.', '6ac8a3de20a10ee24ca3e1de', '2026-10-09T08:20:46.097000'::timestamptz, '2026-10-14T16:33:47.711000'::timestamptz) on conflict (id) do update set "instructional_purpose" = excluded."instructional_purpose", "lesson_code" = excluded."lesson_code", "lesson_id" = excluded."lesson_id", "reviewer_notes" = excluded."reviewer_notes", "research_rationale" = excluded."research_rationale", "proposed_draft_text" = excluded."proposed_draft_text", "decision_note" = excluded."decision_note", "decided_date" = excluded."decided_date", "source_label" = excluded."source_label", "facilitator_boundaries" = excluded."facilitator_boundaries", "source_url" = excluded."source_url", "module_title" = excluded."module_title", "lesson_title" = excluded."lesson_title", "current_card_note" = excluded."current_card_note", "review_scope" = excluded."review_scope", "review_status" = excluded."review_status", "approval_decision" = excluded."approval_decision", "approved_version" = excluded."approved_version", "research_limitations" = excluded."research_limitations", "internal_notes" = excluded."internal_notes", "module_order" = excluded."module_order", "participation_alternatives" = excluded."participation_alternatives", "approver" = excluded."approver", "changes_requested" = excluded."changes_requested", "source_date" = excluded."source_date", "proposed_draft_label" = excluded."proposed_draft_label", "created_date" = excluded."created_date", "updated_date" = excluded."updated_date";
insert into public.lesson_review_package ("instructional_purpose", "lesson_code", "lesson_id", "reviewer_notes", "research_rationale", "proposed_draft_text", "decision_note", "decided_date", "source_label", "facilitator_boundaries", "source_url", "module_title", "lesson_title", "current_card_note", "review_scope", "review_status", "approval_decision", "approved_version", "research_limitations", "internal_notes", "module_order", "participation_alternatives", "approver", "changes_requested", "source_date", "proposed_draft_label", "id", "created_date", "updated_date") values ('Belonging messages fail without real opportunities to belong (Walton et al. 2023, design analogy). Modules 0–7 already practiced tribe threads; this lesson names the “we.”', 'M10-L1', '6acfad71713aa2815e104ed6', 'Proposed prompts inside the draft text are recommendations for review, not approved participant instructions.', 'Research: See sibling Research Guide — Modules 6–8 + Tribe. Key cites: Haslam/Jetten social identity · Steffens ID meta · Walton & Cohen 2011 · Walton et al. 2023 · Forner volunteer turnover. Proposed — not adopted until Ashley approves.

Analogous support: Haslam/Jetten social identity; Steffens ID-building meta; Walton belonging; Wenger communities of practice; Forner volunteer turnover. Counters: social curse, conformity, exclusion of leavers, unpaid labor, forced disclosure, cliques, dependency. Design analogy only.', 'Why this matters
Belonging messages fail without real opportunities to belong (Walton et al. 2023, design analogy). Modules 0–7 already practiced tribe threads; this lesson names the “we.”

Content
Tribe identity; multi-exit belonging; anti-conformity norms (pass, disagree, exit without exile). Optional low-disclosure “what I’m carrying forward” (can be private).

What comes out
Shared identity line + personal exit path named without shame.', '', null, 'Notion — Entrepalooza Curriculum & Evidence Lab · Module 8 working draft · Copy of Ashley Zeck workspace original · Oct 6, 2026 · edits here do not sync.', '- Celebrate no role / not now.
- Do not auto-enroll alumni or follow-up lists.
- Interrupt entrepreneur-only success talk.
- Keep peer roles educational/community — not peer counseling.

- Belonging is not therapy, treatment, or a “social cure” outcome claim — research is design analogy only.
- No trauma disclosure; no hardship-as-marketing; no “scars as admission ticket.”
- No outcome promises (jobs, sobriety, revenue, “found family forever”).
- Entrepreneurship optional; employment choosers celebrated in language and rituals.
- Roles voluntary, revocable, time-bounded, supervised when live; proposed ≠ available.
- Pass / leave / unfollow without exile.
- No cliques-as-curriculum; facilitators interrupt exclusion.
- Dependency watch: tribe supports return-to-evidence and real-life supports — not clinical care and not the only relationship.

- “Real tribe members launch.”
- “Give back for six months.”
- “You’re now a mentor / peer counselor.”
- Forced public testimony or redemption arc.
- Using alumni as unpaid staff for the next cohort.
- Shaming people who chose jobs, left early, or never found a passion.
- Promising the program creates a guaranteed family or recovery community.', 'https://www.notion.so/3f1ca793c2c5816fb0c1fc781d3e7113', 'Build the Tribe', 'Who we are together', 'Existing card retained unchanged, as structure. Teaching on this card is not approved for participant delivery.', 'Optional connection, boundaries, consent, private continuation, and multiple legitimate exits.', 'pending_evaluator_and_clinical_review', '', '', 'Research and theory are used as design lenses, not as proof that Entrepalooza works. Related research does not prove that Entrepalooza works.', '', 10, 'Pass, respond in private, observe, pause, stop, or choose another direction.
A missing worksheet is not a failed module.
Every decision fits one of these labels: Keep, Change, Test Again, Pause/Park, Stop, Another Direction, Continue Looking. "Still don''t know" lives under Continue Looking.', '', 'Status: Working replacement draft for review and rehearsal. Current thin Module 8 lesson cards remain unchanged until this draft is approved. Drops “From Obsession to Legacy” as the participant-facing title.', 'Oct 6, 2026', 'Review candidate — working replacement draft. Not approved teaching, and not part of the participant workbook.', '6ac8a3de20a10ee24ca3e1e9', '2026-10-09T08:20:46.097000'::timestamptz, '2026-10-14T16:34:25.922000'::timestamptz) on conflict (id) do update set "instructional_purpose" = excluded."instructional_purpose", "lesson_code" = excluded."lesson_code", "lesson_id" = excluded."lesson_id", "reviewer_notes" = excluded."reviewer_notes", "research_rationale" = excluded."research_rationale", "proposed_draft_text" = excluded."proposed_draft_text", "decision_note" = excluded."decision_note", "decided_date" = excluded."decided_date", "source_label" = excluded."source_label", "facilitator_boundaries" = excluded."facilitator_boundaries", "source_url" = excluded."source_url", "module_title" = excluded."module_title", "lesson_title" = excluded."lesson_title", "current_card_note" = excluded."current_card_note", "review_scope" = excluded."review_scope", "review_status" = excluded."review_status", "approval_decision" = excluded."approval_decision", "approved_version" = excluded."approved_version", "research_limitations" = excluded."research_limitations", "internal_notes" = excluded."internal_notes", "module_order" = excluded."module_order", "participation_alternatives" = excluded."participation_alternatives", "approver" = excluded."approver", "changes_requested" = excluded."changes_requested", "source_date" = excluded."source_date", "proposed_draft_label" = excluded."proposed_draft_label", "created_date" = excluded."created_date", "updated_date" = excluded."updated_date";
